export interface TranslationEntry {
  surahId: number;
  ayahNumber: number;
  text: string;
}

export const englishTranslation: TranslationEntry[] = [
  { surahId: 1, ayahNumber: 1, text: 'In the name of Allah, the Entirely Merciful, the Especially Merciful.' },
  { surahId: 1, ayahNumber: 2, text: '[All] praise is [due] to Allah, Lord of the worlds -' },
  { surahId: 1, ayahNumber: 3, text: 'The Entirely Merciful, the Especially Merciful,' },
  { surahId: 1, ayahNumber: 4, text: 'Sovereign of the Day of Recompense.' },
  { surahId: 1, ayahNumber: 5, text: 'It is You we worship and You we ask for help.' },
  { surahId: 1, ayahNumber: 6, text: 'Guide us to the straight path -' },
  { surahId: 1, ayahNumber: 7, text: 'The path of those upon whom You have bestowed favor, not of those who have evoked [Your] anger or of those who are astray.' },
  { surahId: 2, ayahNumber: 1, text: 'Alif, Lam, Meem.' },
  { surahId: 2, ayahNumber: 2, text: 'This is the Book about which there is no doubt, a guidance for those conscious of Allah -' },
  { surahId: 2, ayahNumber: 3, text: 'Who believe in the unseen, establish prayer, and spend out of what We have provided for them,' },
  { surahId: 2, ayahNumber: 4, text: 'And who believe in what has been revealed to you, [O Muhammad], and what was revealed before you, and of the Hereafter they are certain [in faith].' },
  { surahId: 2, ayahNumber: 5, text: 'Those are upon [right] guidance from their Lord, and it is those who are the successful.' },
  { surahId: 2, ayahNumber: 6, text: 'Indeed, those who disbelieve - it is all the same for them whether you warn them or do not warn them - they will not believe.' },
  { surahId: 2, ayahNumber: 7, text: 'Allah has set a seal upon their hearts and upon their hearing, and over their vision is a veil. And for them is a great punishment.' },
  { surahId: 2, ayahNumber: 8, text: 'And of the people are some who say, "We believe in Allah and the Last Day," but they are not believers.' },
  { surahId: 2, ayahNumber: 9, text: 'They [think to] deceive Allah and those who believe, but they deceive not except themselves and perceive [it] not.' },
  { surahId: 2, ayahNumber: 10, text: 'In their hearts is disease, so Allah has increased their disease; and for them is a painful punishment because they [habitually] used to lie.' },
  { surahId: 2, ayahNumber: 11, text: 'And when it is said to them, "Do not cause corruption on the earth," they say, "We are but reformers."' },
  { surahId: 2, ayahNumber: 12, text: 'Unquestionably, it is they who are the corrupters, but they perceive [it] not.' },
  { surahId: 2, ayahNumber: 13, text: 'And when it is said to them, "Believe as the people have believed," they say, "Should we believe as the foolish have believed?" Unquestionably, it is they who are the foolish, but they know [it] not.' },
  { surahId: 2, ayahNumber: 14, text: 'And when they meet those who believe, they say, "We believe"; but when they are alone with their evil ones, they say, "Indeed, we are with you; we were only mockers."' },
  { surahId: 2, ayahNumber: 15, text: '[But] Allah mocks them and prolongs them in their transgression [while] they wander blindly.' },
  { surahId: 2, ayahNumber: 16, text: 'Those are the ones who have purchased error [in exchange] for guidance, so their transaction has brought no profit, nor were they guided.' },
  { surahId: 2, ayahNumber: 17, text: 'Their example is that of one who kindled a fire, but when it illuminated what was around him, Allah took away their light and left them in darkness [so] they could not see.' },
  { surahId: 2, ayahNumber: 18, text: 'Deaf, dumb and blind - so they will not return [to the right path].' },
  { surahId: 2, ayahNumber: 19, text: 'Or [it is] like a rainstorm from the sky within which is darkness, thunder and lightning. They put their fingers in their ears against the thunderclaps in dread of death. But Allah is encompassing of the disbelievers.' },
  { surahId: 2, ayahNumber: 20, text: 'The lightning almost snatches away their sight. Every time it lights [the way] for them, they walk therein; but when darkness comes over them, they stand [still]. And if Allah had willed, He could have taken away their hearing and their sight. Indeed, Allah is over all things competent.' },
  { surahId: 2, ayahNumber: 21, text: 'O mankind, worship your Lord, who created you and those before you, that you may become righteous -' },
  { surahId: 2, ayahNumber: 22, text: '[He] who made for you the earth a bed [spread out] and the sky a ceiling and sent down from the sky, rain and brought forth thereby fruits as provision for you. So do not attribute to Allah equals while you know [that there is nothing similar to Him].' },
  { surahId: 2, ayahNumber: 23, text: 'And if you are in doubt about what We have sent down upon Our Servant [Muhammad], then produce a surah the like thereof and call upon your witnesses other than Allah, if you should be truthful.' },
  { surahId: 2, ayahNumber: 24, text: 'But if you do not - and you will never be able to - then fear the Fire, whose fuel is men and stones, prepared for the disbelievers.' },
  { surahId: 2, ayahNumber: 25, text: 'And give good tidings to those who believe and do righteous deeds that they will have gardens [in Paradise] beneath which rivers flow. Whenever they are provided with a provision of fruit therefrom, they will say, "This is what we were provided with before." And it is given to them in likeness. And they will have therein purified spouses, and they will abide therein eternally.' },
  { surahId: 2, ayahNumber: 26, text: 'Indeed, Allah is not timid to present an example - that of a mosquito or what is smaller than it. And those who have believed know that it is the truth from their Lord. But as for those who disbelieve, they say, "What did Allah intend by this as an example?" He misleads many thereby and guides many thereby. And He misleads not except the defiantly disobedient,' },
  { surahId: 2, ayahNumber: 27, text: 'Who break the covenant of Allah after contracting it and sever that which Allah has ordered to be joined and cause corruption on earth. It is those who are the losers.' },
  { surahId: 2, ayahNumber: 28, text: 'How can you disbelieve in Allah when you were lifeless and He brought you to life; then He will cause you to die, then He will bring you [back] to life, and then to Him you will be returned.' },
  { surahId: 2, ayahNumber: 29, text: 'It is He who created for you all of that which is on the earth. Then He directed Himself to the heaven, [His being above all creation], and made them seven heavens, and He is Knowing of all things.' },
  { surahId: 2, ayahNumber: 30, text: 'And [mention, O Muhammad], when your Lord said to the angels, "Indeed, I will make upon the earth a successive authority." They said, "Will You place upon it one who causes corruption therein and sheds blood, while we declare Your praise and sanctify You?" Allah said, "Indeed, I know that which you do not know."' },
  { surahId: 2, ayahNumber: 31, text: 'And He taught Adam the names - all of them. Then He showed them to the angels and said, "Inform Me of the names of these, if you are truthful."' },
  { surahId: 2, ayahNumber: 32, text: 'They said, "Exalted are You; we have no knowledge except what You have taught us. Indeed, it is You who is the Knowing, the Wise."' },
  { surahId: 2, ayahNumber: 33, text: 'He said, "O Adam, inform them of their names." And when he had informed them of their names, He said, "Did I not tell you that I know the unseen [aspects] of the heavens and the earth? And I know what you reveal and what you have concealed."' },
  { surahId: 2, ayahNumber: 34, text: 'And [mention] when We said to the angels, "Prostrate before Adam"; so they prostrated, except for Iblees. He refused and was arrogant and became of the disbelievers.' },
  { surahId: 2, ayahNumber: 35, text: 'And We said, "O Adam, dwell, you and your wife, in Paradise and eat therefrom in [ease and] abundance from wherever you will. But do not approach this tree, lest you be among the wrongdoers."' },
  { surahId: 2, ayahNumber: 36, text: 'But Satan caused them to slip out of it and removed them from that [condition] in which they had been. And We said, "Go down, [all of you], as enemies to one another, and you will have upon the earth a place of settlement and provision for a time."' },
  { surahId: 2, ayahNumber: 37, text: 'Then Adam received from his Lord [some] words, and He accepted his repentance. Indeed, it is He who is the Accepting of repentance, the Merciful.' },
  { surahId: 2, ayahNumber: 38, text: 'We said, "Go down from it, all of you. And when guidance comes to you from Me, whoever follows My guidance - there will be no fear concerning them, nor will they grieve.' },
  { surahId: 2, ayahNumber: 39, text: 'And those who disbelieve and deny Our signs - those will be companions of the Fire; they will abide therein eternally."' },
  { surahId: 2, ayahNumber: 40, text: 'O Children of Israel, remember My favor which I have bestowed upon you and fulfill My covenant [upon you] that I will fulfill your covenant [from Me], and be afraid of [only] Me.' },
  { surahId: 2, ayahNumber: 41, text: 'And believe in what I have sent down confirming that which is [already] with you, and be not the first to disbelieve in it. And do not exchange My signs for a small price, and fear [only] Me.' },
  { surahId: 2, ayahNumber: 42, text: 'And do not mix the truth with falsehood or conceal the truth while you know [it].' },
  { surahId: 2, ayahNumber: 43, text: 'And establish prayer and give zakah and bow with those who bow [in worship and obedience].' },
  { surahId: 2, ayahNumber: 44, text: 'Do you order righteousness of the people and forget yourselves while you recite the Scripture? Then will you not reason?' },
  { surahId: 2, ayahNumber: 45, text: 'And seek help through patience and prayer, and indeed, it is difficult except for the humbly submissive [to Allah]' },
  { surahId: 2, ayahNumber: 46, text: 'Who are certain that they will meet their Lord and that they will return to Him.' },
  { surahId: 2, ayahNumber: 47, text: 'O Children of Israel, remember My favor that I have bestowed upon you and that I preferred you over the worlds.' },
  { surahId: 2, ayahNumber: 48, text: 'And fear a Day when no soul will suffice for another soul at all, nor will intercession be accepted from it, nor will compensation be taken from it, nor will they be aided.' },
  { surahId: 2, ayahNumber: 49, text: 'And [recall] when We saved your forefathers from the people of Pharaoh, who afflicted you with the worst torment, slaughtering your [newborn] sons and keeping your females alive. And in that was a great trial from your Lord.' },
  { surahId: 2, ayahNumber: 50, text: 'And [recall] when We parted the sea for you and saved you and drowned the people of Pharaoh while you were looking on.' },
  { surahId: 2, ayahNumber: 51, text: 'And [recall] when We made an appointment with Moses for forty nights. Then you took [for worship] the calf after him, while you were wrongdoers.' },
  { surahId: 2, ayahNumber: 52, text: 'Then We forgave you after that so perhaps you would be grateful.' },
  { surahId: 2, ayahNumber: 53, text: 'And [recall] when We gave Moses the Scripture and criterion that perhaps you would be guided.' },
  { surahId: 2, ayahNumber: 54, text: 'And [recall] when Moses said to his people, "O my people, indeed you have wronged yourselves by your taking of the calf [for worship]. So repent to your Creator and kill yourselves. That is best for [all of] you in the sight of your Creator." Then He accepted your repentance; indeed, He is the Accepting of repentance, the Merciful.' },
  { surahId: 2, ayahNumber: 55, text: 'And [recall] when you said, "O Moses, we will never believe you until we see Allah outright"; so the thunderbolt took you while you were looking on.' },
  { surahId: 2, ayahNumber: 56, text: 'Then We revived you after your death that perhaps you would be grateful.' },
  { surahId: 2, ayahNumber: 57, text: 'And We shaded you with clouds and sent down to you manna and quails, [saying], "Eat from the good things with which We have provided you." And they wronged Us not - but they were [only] wronging themselves.' },
  { surahId: 2, ayahNumber: 58, text: 'And [recall] when We said, "Enter this city and eat from it wherever you will in [ease and] abundance, and enter the gate bowing humbly and say, \'Relieve us of our burdens.\' We will [then] forgive your sins for you, and We will increase the doers of good [in goodness and reward]."' },
  { surahId: 2, ayahNumber: 59, text: 'But those who wronged changed [those words] to a statement other than that which had been said to them, so We sent down upon those who wronged a punishment from the sky because they were defiantly disobeying.' },
  { surahId: 2, ayahNumber: 60, text: 'And [recall] when Moses prayed for water for his people, so We said, "Strike with your staff the stone." And there gushed forth from it twelve springs, and every people knew its watering place. "Eat and drink from the provision of Allah, and do not commit abuse on the earth, spreading corruption."' },
  { surahId: 2, ayahNumber: 61, text: 'And [recall] when you said, "O Moses, we can never endure one [kind of] food. So call upon your Lord to bring forth for us from the earth its green herbs and its cucumbers and its garlic and its lentils and its onions." [Moses] said, "Would you exchange what is better for what is less? Go into [any] settlement and indeed, you will have what you have asked." And they were covered with humiliation and poverty and returned with anger from Allah [upon them]. That was because they [repeatedly] disbelieved in the signs of Allah and killed the prophets without right. That was because they disobeyed and were [habitually] transgressing.' },
  { surahId: 2, ayahNumber: 62, text: 'Indeed, those who believed and those who were Jews or Christians or Sabeans [before Prophet Muhammad] - those [among them] who believed in Allah and the Last Day and did righteousness - will have their reward with their Lord, and no fear will there be concerning them, nor will they grieve.' },
  { surahId: 2, ayahNumber: 63, text: 'And [recall] when We took your covenant, [O Children of Israel, to abide by the Torah] and We raised over you the mount, [saying], "Take what We have given you with determination and remember what is in it that perhaps you may become righteous."' },
  { surahId: 2, ayahNumber: 64, text: 'Then you turned away after that. And if not for the favor of Allah upon you and His mercy, you would have been among the losers.' },
  { surahId: 2, ayahNumber: 65, text: 'And you had already known about those who transgressed among you concerning the sabbath, and We said to them, "Be apes, despised."' },
  { surahId: 2, ayahNumber: 66, text: 'And We made it a deterrent punishment for those who were present and those who succeeded [them] and a lesson for those who fear Allah.' },
  { surahId: 2, ayahNumber: 67, text: 'And [recall] when Moses said to his people, "Indeed, Allah commands you to slaughter a cow." They said, "Do you take us in ridicule?" He said, "I seek refuge in Allah from being among the ignorant."' },
  { surahId: 2, ayahNumber: 68, text: 'They said, "Call upon your Lord to make clear to us what it is." [Moses] said, "[Allah] says, \'It is a cow which is neither old nor virgin, but median between that,\' so do what you are commanded."' },
  { surahId: 2, ayahNumber: 69, text: 'They said, "Call upon your Lord to show us what is her color." He said, "He says, \'It is a yellow cow, bright in color - pleasing to the observers.\' "' },
  { surahId: 2, ayahNumber: 70, text: 'They said, "Call upon your Lord to make clear to us what it is. Indeed, [all] cows look alike to us. And indeed we, if Allah wills, will be guided."' },
  { surahId: 2, ayahNumber: 71, text: 'He said, "He says, \'It is a cow neither trained to plow the earth nor to irrigate the field, one free from fault with no spot upon her.\' " They said, "Now you have come with the truth." So they slaughtered her, but they could hardly do it.' },
  { surahId: 2, ayahNumber: 72, text: 'And [recall] when you slew a man and disputed over it, but Allah was to bring out that which you were concealing.' },
  { surahId: 2, ayahNumber: 73, text: 'So, We said, "Strike the slain man with part of it." Thus does Allah bring the dead to life, and He shows you His signs that you might reason.' },
  { surahId: 2, ayahNumber: 74, text: 'Then your hearts became hardened after that, being like stones or even harder. For indeed, there are stones from which rivers burst forth, and there are some of them that split open and water comes out, and there are some of them that fall down for fear of Allah. And Allah is not unaware of what you do.' },
  { surahId: 2, ayahNumber: 75, text: 'Do you covet [the hope, O believers], that they would believe for you while a party of them used to hear the words of Allah and then distort the Torah after they had understood it while they were knowing?' },
  { surahId: 2, ayahNumber: 76, text: 'And when they meet those who believe, they say, "We have believed"; but when they are alone with one another, they say, "Do you talk to them about what Allah has revealed to you so they can argue with you about it before your Lord?" Then will you not reason?' },
  { surahId: 2, ayahNumber: 77, text: 'But do they not know that Allah knows what they conceal and what they declare?' },
  { surahId: 2, ayahNumber: 78, text: 'And among them are unlettered ones who do not know the Scripture except in wishful thinking, but they are only assuming.' },
  { surahId: 2, ayahNumber: 79, text: 'So woe to those who write the "scripture" with their own hands, then say, "This is from Allah," in order to exchange it for a small price. Woe to them for what their hands have written and woe to them for what they earn.' },
  { surahId: 2, ayahNumber: 80, text: 'And they say, "Never will the Fire touch us, except for a few days." Say, "Have you taken a covenant with Allah? For Allah will never break His covenant. Or do you say about Allah that which you do not know?"' },
  { surahId: 2, ayahNumber: 81, text: 'Yes, whoever earns evil and his sin has encompassed him - those are the companions of the Fire; they will abide therein eternally.' },
  { surahId: 2, ayahNumber: 82, text: 'But they who believe and do righteous deeds - those are the companions of Paradise; they will abide therein eternally.' },
  { surahId: 2, ayahNumber: 83, text: 'And [recall] when We took the covenant from the Children of Israel, [enjoining upon them], "Do not worship except Allah; and to parents do good and to relatives, orphans, and the needy. And speak to people good [words] and establish prayer and give zakah." Then you turned away, except a few of you, and you were refusing.' },
  { surahId: 2, ayahNumber: 84, text: 'And [recall] when We took your covenant, [saying], "Do not shed each other\'s blood or evict one another from your homes." Then you acknowledged [this] while you were witnessing.' },
  { surahId: 2, ayahNumber: 85, text: 'Then, you are those [same ones who are] killing one another and evicting a party of your people from their homes, cooperating against them in sin and aggression. And if they come to you as captives, you ransom them, although their eviction was forbidden to you. So do you believe in part of the Scripture and disbelieve in part? Then what is the recompense for those who do that among you except disgrace in worldly life; and on the Day of Resurrection they will be sent back to the severest of punishment. And Allah is not unaware of what you do.' },
  { surahId: 2, ayahNumber: 86, text: 'Those are the ones who have bought the life of this world [in exchange] for the Hereafter, so the punishment will not be lightened for them, nor will they be aided.' },
  { surahId: 2, ayahNumber: 87, text: 'And We did certainly give Moses the Torah and followed up after him with messengers. And We gave Jesus, the son of Mary, clear proofs and supported him with the Pure Spirit. But is it [not] that every time a messenger came to you, [O Children of Israel], with what your souls did not desire, you were arrogant? And a party [of messengers] you denied and another party you killed.' },
  { surahId: 2, ayahNumber: 88, text: 'And they said, "Our hearts are wrapped." But, [in fact], Allah has cursed them for their disbelief, so little is it that they believe.' },
  { surahId: 2, ayahNumber: 89, text: 'And when there came to them a Book from Allah confirming that which was with them - although before they used to pray for victory against those who disbelieved - but [then] when there came to them that which they recognized, they disbelieved in it; so the curse of Allah will be upon the disbelievers.' },
  { surahId: 2, ayahNumber: 90, text: 'How wretched is that for which they sold themselves - that they would disbelieve in what Allah has revealed through [their] outrage that Allah would send down His favor upon whom He wills from among His servants. So they returned having [earned] wrath upon wrath. And for the disbelievers is a humiliating punishment.' },
  { surahId: 2, ayahNumber: 91, text: 'And when it is said to them, "Believe in what Allah has revealed," they say, "We believe [only] in what was revealed to us." And they disbelieve in what came after it, while it is the truth confirming that which is with them. Say, "Then why did you kill the prophets of Allah before, if you are [indeed] believers?"' },
  { surahId: 2, ayahNumber: 92, text: 'And Moses had certainly brought you clear proofs. Then you took the calf [in worship] after that, while you were wrongdoers.' },
  { surahId: 2, ayahNumber: 93, text: 'And [recall] when We took your covenant and raised over you the mount, [saying], "Take what We have given you with determination and listen." They said [instead], "We hear and disobey." And their hearts absorbed [the worship of] the calf because of their disbelief. Say, "How wretched is that which your faith enjoins upon you, if you should be believers."' },
  { surahId: 2, ayahNumber: 94, text: 'Say, [O Muhammad], "If the home of the Hereafter with Allah is for you alone and not the [other] people, then wish for death, if you should be truthful.' },
  { surahId: 2, ayahNumber: 95, text: 'But they will never wish for it, ever, because of what their hands have put forth. And Allah is Knowing of the wrongdoers.' },
  { surahId: 2, ayahNumber: 96, text: 'And you will surely find them the most greedy of people for life - [even] more than those who associate others with Allah. One of them wishes that he could be granted life a thousand years, but it would not remove him in the least from the [coming] punishment that he should be granted life. And Allah is Seeing of what they do.' },
  { surahId: 2, ayahNumber: 97, text: 'Say, "Whoever is an enemy to Gabriel - it is [none but] he who has brought the Qur\'an down upon your heart, [O Muhammad], by permission of Allah, confirming that which was before it and as guidance and good tidings for the believers."' },
  { surahId: 2, ayahNumber: 98, text: 'Whoever is an enemy to Allah and His angels and His messengers and Gabriel and Michael - then indeed, Allah is an enemy to the disbelievers.' },
  { surahId: 2, ayahNumber: 99, text: 'And We have certainly revealed to you verses [which are] clear proofs, and no one would deny them except the defiantly disobedient.' },
  { surahId: 2, ayahNumber: 100, text: 'Is it not [true] that every time they took a covenant a party of them threw it away? But, [in fact], most of them do not believe.' },
  { surahId: 2, ayahNumber: 101, text: 'And when a messenger from Allah came to them confirming that which was with them, a party of those who had been given the Scripture threw the Scripture of Allah behind their backs as if they did not know [what it contained].' },
  { surahId: 2, ayahNumber: 102, text: 'And they followed [instead] what the devils had recited during the reign of Solomon. It was not Solomon who disbelieved, but the devils disbelieved, teaching people magic and that which was revealed to the two angels at Babylon, Harut and Marut. But the two angels do not teach anyone unless they say, "We are a trial, so do not disbelieve [by practicing magic]." And [yet] they learn from them that by which they cause separation between a man and his wife. But they do not harm anyone through it except by permission of Allah. And the people learn what harms them and does not benefit them. But the Children of Israel certainly knew that whoever purchased the magic would not have in the Hereafter any share. And wretched is that for which they sold themselves, if they only knew.' },
  { surahId: 2, ayahNumber: 103, text: 'And if they had believed and feared Allah, then the reward from Allah would have been [far] better, if they only knew.' },
  { surahId: 2, ayahNumber: 104, text: 'O you who have believed, say not [to Allah \'s Messenger], "Ra\'ina" but say, "Unthurna" and listen. And for the disbelievers is a painful punishment.' },
  { surahId: 2, ayahNumber: 105, text: 'Neither those who disbelieve from the People of the Scripture nor the polytheists wish that any good should be sent down to you from your Lord. But Allah selects for His mercy whom He wills, and Allah is the possessor of great bounty.' },
  { surahId: 2, ayahNumber: 106, text: 'We do not abrogate a verse or cause it to be forgotten except that We bring forth [one] better than it or similar to it. Do you not know that Allah is over all things competent?' },
  { surahId: 2, ayahNumber: 107, text: 'Do you not know that to Allah belongs the dominion of the heavens and the earth and [that] you have not besides Allah any protector or any helper?' },
  { surahId: 2, ayahNumber: 108, text: 'Or do you intend to ask your Messenger as Moses was asked before? And whoever exchanges faith for disbelief has certainly strayed from the soundness of the way.' },
  { surahId: 2, ayahNumber: 109, text: 'Many of the People of the Scripture wish they could turn you back to disbelief after you have believed, out of envy from themselves [even] after the truth has become clear to them. So pardon and overlook until Allah delivers His command. Indeed, Allah is over all things competent.' },
  { surahId: 2, ayahNumber: 110, text: 'And establish prayer and give zakah, and whatever good you put forward for yourselves - you will find it with Allah. Indeed, Allah of what you do, is Seeing.' },
  { surahId: 2, ayahNumber: 111, text: 'And they say, "None will enter Paradise except one who is a Jew or a Christian." That is [merely] their wishful thinking, Say, "Produce your proof, if you should be truthful."' },
  { surahId: 2, ayahNumber: 112, text: 'Yes [on the contrary], whoever submits his face in Islam to Allah while being a doer of good will have his reward with his Lord. And no fear will there be concerning them, nor will they grieve.' },
  { surahId: 2, ayahNumber: 113, text: 'The Jews say "The Christians have nothing [true] to stand on," and the Christians say, "The Jews have nothing to stand on," although they [both] recite the Scripture. Thus the polytheists speak the same as their words. But Allah will judge between them on the Day of Resurrection concerning that over which they used to differ.' },
  { surahId: 2, ayahNumber: 114, text: 'And who are more unjust than those who prevent the name of Allah from being mentioned in His mosques and strive toward their destruction. It is not for them to enter them except in fear. For them in this world is disgrace, and they will have in the Hereafter a great punishment.' },
  { surahId: 2, ayahNumber: 115, text: 'And to Allah belongs the east and the west. So wherever you [might] turn, there is the Face of Allah. Indeed, Allah is all-Encompassing and Knowing.' },
  { surahId: 2, ayahNumber: 116, text: 'They say, "Allah has taken a son." Exalted is He! Rather, to Him belongs whatever is in the heavens and the earth. All are devoutly obedient to Him,' },
  { surahId: 2, ayahNumber: 117, text: 'Originator of the heavens and the earth. When He decrees a matter, He only says to it, "Be," and it is.' },
  { surahId: 2, ayahNumber: 118, text: 'Those who do not know say, "Why does Allah not speak to us or there come to us a sign?" Thus spoke those before them like their words. Their hearts resemble each other. We have shown clearly the signs to a people who are certain [in faith].' },
  { surahId: 2, ayahNumber: 119, text: 'Indeed, We have sent you, [O Muhammad], with the truth as a bringer of good tidings and a warner, and you will not be asked about the companions of Hellfire.' },
  { surahId: 2, ayahNumber: 120, text: 'And never will the Jews or the Christians approve of you until you follow their religion. Say, "Indeed, the guidance of Allah is the [only] guidance." If you were to follow their desires after what has come to you of knowledge, you would have against Allah no protector or helper.' },
  { surahId: 2, ayahNumber: 121, text: 'Those to whom We have given the Book recite it with its true recital. They [are the ones who] believe in it. And whoever disbelieves in it - it is they who are the losers.' },
  { surahId: 2, ayahNumber: 122, text: 'O Children of Israel, remember My favor which I have bestowed upon you and that I preferred you over the worlds.' },
  { surahId: 2, ayahNumber: 123, text: 'And fear a Day when no soul will suffice for another soul at all, and no compensation will be accepted from it, nor will any intercession benefit it, nor will they be aided.' },
  { surahId: 2, ayahNumber: 124, text: 'And [mention, O Muhammad], when Abraham was tried by his Lord with commands and he fulfilled them. [Allah] said, "Indeed, I will make you a leader for the people." [Abraham] said, "And of my descendants?" [Allah] said, "My covenant does not include the wrongdoers."' },
  { surahId: 2, ayahNumber: 125, text: 'And [mention] when We made the House a place of return for the people and [a place of] security. And take, [O believers], from the standing place of Abraham a place of prayer. And We charged Abraham and Ishmael, [saying], "Purify My House for those who perform Tawaf and those who are staying [there] for worship and those who bow and prostrate [in prayer]."' },
  { surahId: 2, ayahNumber: 126, text: 'And [mention] when Abraham said, "My Lord, make this a secure city and provide its people with fruits - whoever of them believes in Allah and the Last Day." [Allah] said. "And whoever disbelieves - I will grant him enjoyment for a little; then I will force him to the punishment of the Fire, and wretched is the destination."' },
  { surahId: 2, ayahNumber: 127, text: 'And [mention] when Abraham was raising the foundations of the House and [with him] Ishmael, [saying], "Our Lord, accept [this] from us. Indeed You are the Hearing, the Knowing.' },
  { surahId: 2, ayahNumber: 128, text: 'Our Lord, and make us Muslims [in submission] to You and from our descendants a Muslim nation [in submission] to You. And show us our rites and accept our repentance. Indeed, You are the Accepting of repentance, the Merciful.' },
  { surahId: 2, ayahNumber: 129, text: 'Our Lord, and send among them a messenger from themselves who will recite to them Your verses and teach them the Book and wisdom and purify them. Indeed, You are the Exalted in Might, the Wise."' },
  { surahId: 2, ayahNumber: 130, text: 'And who would be averse to the religion of Abraham except one who makes a fool of himself. And We had chosen him in this world, and indeed he, in the Hereafter, will be among the righteous.' },
  { surahId: 2, ayahNumber: 131, text: 'When his Lord said to him, "Submit", he said "I have submitted [in Islam] to the Lord of the worlds."' },
  { surahId: 2, ayahNumber: 132, text: 'And Abraham instructed his sons [to do the same] and [so did] Jacob, [saying], "O my sons, indeed Allah has chosen for you this religion, so do not die except while you are Muslims."' },
  { surahId: 2, ayahNumber: 133, text: 'Or were you witnesses when death approached Jacob, when he said to his sons, "What will you worship after me?" They said, "We will worship your God and the God of your fathers, Abraham and Ishmael and Isaac - one God. And we are Muslims [in submission] to Him."' },
  { surahId: 2, ayahNumber: 134, text: 'That was a nation which has passed on. It will have [the consequence of] what it earned, and you will have what you have earned. And you will not be asked about what they used to do.' },
  { surahId: 2, ayahNumber: 135, text: 'They say, "Be Jews or Christians [so] you will be guided." Say, "Rather, [we follow] the religion of Abraham, inclining toward truth, and he was not of the polytheists."' },
  { surahId: 2, ayahNumber: 136, text: 'Say, [O believers], "We have believed in Allah and what has been revealed to us and what has been revealed to Abraham and Ishmael and Isaac and Jacob and the Descendants and what was given to Moses and Jesus and what was given to the prophets from their Lord. We make no distinction between any of them, and we are Muslims [in submission] to Him."' },
  { surahId: 2, ayahNumber: 137, text: 'So if they believe in the same as you believe in, then they have been [rightly] guided; but if they turn away, they are only in dissension, and Allah will be sufficient for you against them. And He is the Hearing, the Knowing.' },
  { surahId: 2, ayahNumber: 138, text: '[And say, "Ours is] the religion of Allah. And who is better than Allah in [ordaining] religion? And we are worshippers of Him."' },
  { surahId: 2, ayahNumber: 139, text: 'Say, [O Muhammad], "Do you argue with us about Allah while He is our Lord and your Lord? For us are our deeds, and for you are your deeds. And we are sincere [in deed and intention] to Him."' },
  { surahId: 2, ayahNumber: 140, text: 'Or do you say that Abraham and Ishmael and Isaac and Jacob and the Descendants were Jews or Christians? Say, "Are you more knowing or is Allah?" And who is more unjust than one who conceals a testimony he has from Allah? And Allah is not unaware of what you do.' },
  { surahId: 2, ayahNumber: 141, text: 'That is a nation which has passed on. It will have [the consequence of] what it earned, and you will have what you have earned. And you will not be asked about what they used to do.' },
  { surahId: 2, ayahNumber: 142, text: 'The foolish among the people will say, "What has turned them away from their qiblah, which they used to face?" Say, "To Allah belongs the east and the west. He guides whom He wills to a straight path."' },
  { surahId: 2, ayahNumber: 143, text: 'And thus we have made you a just community that you will be witnesses over the people and the Messenger will be a witness over you. And We did not make the qiblah which you used to face except that We might make evident who would follow the Messenger from who would turn back on his heels. And indeed, it is difficult except for those whom Allah has guided. And never would Allah have caused you to lose your faith. Indeed Allah is, to the people, Kind and Merciful.' },
  { surahId: 2, ayahNumber: 144, text: 'We have certainly seen the turning of your face, [O Muhammad], toward the heaven, and We will surely turn you to a qiblah with which you will be pleased. So turn your face toward al-Masjid al-Haram. And wherever you [believers] are, turn your faces toward it [in prayer]. Indeed, those who have been given the Scripture well know that it is the truth from their Lord. And Allah is not unaware of what they do.' },
  { surahId: 2, ayahNumber: 145, text: 'And if you brought to those who were given the Scripture every sign, they would not follow your qiblah. Nor will you be a follower of their qiblah. Nor would they be followers of one another\'s qiblah. So if you were to follow their desires after what has come to you of knowledge, indeed, you would then be among the wrongdoers.' },
  { surahId: 2, ayahNumber: 146, text: 'Those to whom We gave the Scripture know him as they know their own sons. But indeed, a party of them conceal the truth while they know [it].' },
  { surahId: 2, ayahNumber: 147, text: 'The truth is from your Lord, so never be among the doubters.' },
  { surahId: 2, ayahNumber: 148, text: 'For each [religious following] is a direction toward which it faces. So race to [all that is] good. Wherever you may be, Allah will bring you forth [for judgement] all together. Indeed, Allah is over all things competent.' },
  { surahId: 2, ayahNumber: 149, text: 'So from wherever you go out [for prayer, O Muhammad] turn your face toward al- Masjid al-Haram, and indeed, it is the truth from your Lord. And Allah is not unaware of what you do.' },
  { surahId: 2, ayahNumber: 150, text: 'And from wherever you go out [for prayer], turn your face toward al-Masjid al-Haram. And wherever you [believers] may be, turn your faces toward it in order that the people will not have any argument against you, except for those of them who commit wrong; so fear them not but fear Me. And [it is] so I may complete My favor upon you and that you may be guided.' },
  { surahId: 2, ayahNumber: 151, text: 'Just as We have sent among you a messenger from yourselves reciting to you Our verses and purifying you and teaching you the Book and wisdom and teaching you that which you did not know.' },
  { surahId: 2, ayahNumber: 152, text: 'So remember Me; I will remember you. And be grateful to Me and do not deny Me.' },
  { surahId: 2, ayahNumber: 153, text: 'O you who have believed, seek help through patience and prayer. Indeed, Allah is with the patient.' },
  { surahId: 2, ayahNumber: 154, text: 'And do not say about those who are killed in the way of Allah, "They are dead." Rather, they are alive, but you perceive [it] not.' },
  { surahId: 2, ayahNumber: 155, text: 'And We will surely test you with something of fear and hunger and a loss of wealth and lives and fruits, but give good tidings to the patient,' },
  { surahId: 2, ayahNumber: 156, text: 'Who, when disaster strikes them, say, "Indeed we belong to Allah, and indeed to Him we will return."' },
  { surahId: 2, ayahNumber: 157, text: 'Those are the ones upon whom are blessings from their Lord and mercy. And it is those who are the [rightly] guided.' },
  { surahId: 2, ayahNumber: 158, text: 'Indeed, as-Safa and al-Marwah are among the symbols of Allah. So whoever makes Hajj to the House or performs \'umrah - there is no blame upon him for walking between them. And whoever volunteers good - then indeed, Allah is appreciative and Knowing.' },
  { surahId: 2, ayahNumber: 159, text: 'Indeed, those who conceal what We sent down of clear proofs and guidance after We made it clear for the people in the Scripture - those are cursed by Allah and cursed by those who curse,' },
  { surahId: 2, ayahNumber: 160, text: 'Except for those who repent and correct themselves and make evident [what they concealed]. Those - I will accept their repentance, and I am the Accepting of repentance, the Merciful.' },
  { surahId: 2, ayahNumber: 161, text: 'Indeed, those who disbelieve and die while they are disbelievers - upon them will be the curse of Allah and of the angels and the people, all together,' },
  { surahId: 2, ayahNumber: 162, text: 'Abiding eternally therein. The punishment will not be lightened for them, nor will they be reprieved.' },
  { surahId: 2, ayahNumber: 163, text: 'And your god is one God. There is no deity [worthy of worship] except Him, the Entirely Merciful, the Especially Merciful.' },
  { surahId: 2, ayahNumber: 164, text: 'Indeed, in the creation of the heavens and earth, and the alternation of the night and the day, and the [great] ships which sail through the sea with that which benefits people, and what Allah has sent down from the heavens of rain, giving life thereby to the earth after its lifelessness and dispersing therein every [kind of] moving creature, and [His] directing of the winds and the clouds controlled between the heaven and the earth are signs for a people who use reason.' },
  { surahId: 2, ayahNumber: 165, text: 'And [yet], among the people are those who take other than Allah as equals [to Him]. They love them as they [should] love Allah. But those who believe are stronger in love for Allah. And if only they who have wronged would consider [that] when they see the punishment, [they will be certain] that all power belongs to Allah and that Allah is severe in punishment.' },
  { surahId: 2, ayahNumber: 166, text: '[And they should consider that] when those who have been followed disassociate themselves from those who followed [them], and they [all] see the punishment, and cut off from them are the ties [of relationship],' },
  { surahId: 2, ayahNumber: 167, text: 'Those who followed will say, "If only we had another turn [at worldly life] so we could disassociate ourselves from them as they have disassociated themselves from us." Thus will Allah show them their deeds as regrets upon them. And they are never to emerge from the Fire.' },
  { surahId: 2, ayahNumber: 168, text: 'O mankind, eat from whatever is on earth [that is] lawful and good and do not follow the footsteps of Satan. Indeed, he is to you a clear enemy.' },
  { surahId: 2, ayahNumber: 169, text: 'He only orders you to evil and immorality and to say about Allah what you do not know.' },
  { surahId: 2, ayahNumber: 170, text: 'And when it is said to them, "Follow what Allah has revealed," they say, "Rather, we will follow that which we found our fathers doing." Even though their fathers understood nothing, nor were they guided?' },
  { surahId: 2, ayahNumber: 171, text: 'The example of those who disbelieve is like that of one who shouts at what hears nothing but calls and cries cattle or sheep - deaf, dumb and blind, so they do not understand.' },
  { surahId: 2, ayahNumber: 172, text: 'O you who have believed, eat from the good things which We have provided for you and be grateful to Allah if it is [indeed] Him that you worship.' },
  { surahId: 2, ayahNumber: 173, text: 'He has only forbidden to you dead animals, blood, the flesh of swine, and that which has been dedicated to other than Allah. But whoever is forced [by necessity], neither desiring [it] nor transgressing [its limit], there is no sin upon him. Indeed, Allah is Forgiving and Merciful.' },
  { surahId: 2, ayahNumber: 174, text: 'Indeed, they who conceal what Allah has sent down of the Book and exchange it for a small price - those consume not into their bellies except the Fire. And Allah will not speak to them on the Day of Resurrection, nor will He purify them. And they will have a painful punishment.' },
  { surahId: 2, ayahNumber: 175, text: 'Those are the ones who have exchanged guidance for error and forgiveness for punishment. How patient they are in pursuit of the Fire!' },
  { surahId: 2, ayahNumber: 176, text: 'That is [deserved by them] because Allah has sent down the Book in truth. And indeed, those who differ over the Book are in extreme dissension.' },
  { surahId: 2, ayahNumber: 177, text: 'Righteousness is not that you turn your faces toward the east or the west, but [true] righteousness is [in] one who believes in Allah, the Last Day, the angels, the Book, and the prophets and gives wealth, in spite of love for it, to relatives, orphans, the needy, the traveler, those who ask [for help], and for freeing slaves; [and who] establishes prayer and gives zakah; [those who] fulfill their promise when they promise; and [those who] are patient in poverty and hardship and during battle. Those are the ones who have been true, and it is those who are the righteous.' },
  { surahId: 2, ayahNumber: 178, text: 'O you who have believed, prescribed for you is legal retribution for those murdered - the free for the free, the slave for the slave, and the female for the female. But whoever overlooks from his brother anything, then there should be a suitable follow-up and payment to him with good conduct. This is an alleviation from your Lord and a mercy. But whoever transgresses after that will have a painful punishment.' },
  { surahId: 2, ayahNumber: 179, text: 'And there is for you in legal retribution [saving of] life, O you [people] of understanding, that you may become righteous.' },
  { surahId: 2, ayahNumber: 180, text: 'Prescribed for you when death approaches [any] one of you if he leaves wealth [is that he should make] a bequest for the parents and near relatives according to what is acceptable - a duty upon the righteous.' },
  { surahId: 2, ayahNumber: 181, text: 'Then whoever alters the bequest after he has heard it - the sin is only upon those who have altered it. Indeed, Allah is Hearing and Knowing.' },
  { surahId: 2, ayahNumber: 182, text: 'But if one fears from the bequeather [some] error or sin and corrects that which is between them, there is no sin upon him. Indeed, Allah is Forgiving and Merciful.' },
  { surahId: 2, ayahNumber: 183, text: 'O you who have believed, decreed upon you is fasting as it was decreed upon those before you that you may become righteous -' },
  { surahId: 2, ayahNumber: 184, text: '[Fasting for] a limited number of days. So whoever among you is ill or on a journey [during them] - then an equal number of days [are to be made up]. And upon those who are able [to fast, but with hardship] - a ransom [as substitute] of feeding a poor person [each day]. And whoever volunteers excess - it is better for him. But to fast is best for you, if you only knew.' },
  { surahId: 2, ayahNumber: 185, text: 'The month of Ramadhan [is that] in which was revealed the Qur\'an, a guidance for the people and clear proofs of guidance and criterion. So whoever sights [the new moon of] the month, let him fast it; and whoever is ill or on a journey - then an equal number of other days. Allah intends for you ease and does not intend for you hardship and [wants] for you to complete the period and to glorify Allah for that [to] which He has guided you; and perhaps you will be grateful.' },
  { surahId: 2, ayahNumber: 186, text: 'And when My servants ask you, [O Muhammad], concerning Me - indeed I am near. I respond to the invocation of the supplicant when he calls upon Me. So let them respond to Me [by obedience] and believe in Me that they may be [rightly] guided.' },
  { surahId: 2, ayahNumber: 187, text: 'It has been made permissible for you the night preceding fasting to go to your wives [for sexual relations]. They are clothing for you and you are clothing for them. Allah knows that you used to deceive yourselves, so He accepted your repentance and forgave you. So now, have relations with them and seek that which Allah has decreed for you. And eat and drink until the white thread of dawn becomes distinct to you from the black thread [of night]. Then complete the fast until the sunset. And do not have relations with them as long as you are staying for worship in the mosques. These are the limits [set by] Allah, so do not approach them. Thus does Allah make clear His ordinances to the people that they may become righteous.' },
  { surahId: 2, ayahNumber: 188, text: 'And do not consume one another\'s wealth unjustly or send it [in bribery] to the rulers in order that [they might aid] you [to] consume a portion of the wealth of the people in sin, while you know [it is unlawful].' },
  { surahId: 2, ayahNumber: 189, text: 'They ask you, [O Muhammad], about the new moons. Say, "They are measurements of time for the people and for Hajj." And it is not righteousness to enter houses from the back, but righteousness is [in] one who fears Allah. And enter houses from their doors. And fear Allah that you may succeed.' },
  { surahId: 2, ayahNumber: 190, text: 'Fight in the way of Allah those who fight you but do not transgress. Indeed. Allah does not like transgressors.' },
  { surahId: 2, ayahNumber: 191, text: 'And kill them wherever you overtake them and expel them from wherever they have expelled you, and fitnah is worse than killing. And do not fight them at al-Masjid al- Haram until they fight you there. But if they fight you, then kill them. Such is the recompense of the disbelievers.' },
  { surahId: 2, ayahNumber: 192, text: 'And if they cease, then indeed, Allah is Forgiving and Merciful.' },
  { surahId: 2, ayahNumber: 193, text: 'Fight them until there is no [more] fitnah and [until] worship is [acknowledged to be] for Allah. But if they cease, then there is to be no aggression except against the oppressors.' },
  { surahId: 2, ayahNumber: 194, text: '[Fighting in] the sacred month is for [aggression committed in] the sacred month, and for [all] violations is legal retribution. So whoever has assaulted you, then assault him in the same way that he has assaulted you. And fear Allah and know that Allah is with those who fear Him.' },
  { surahId: 2, ayahNumber: 195, text: 'And spend in the way of Allah and do not throw [yourselves] with your [own] hands into destruction [by refraining]. And do good; indeed, Allah loves the doers of good.' },
  { surahId: 2, ayahNumber: 196, text: 'And complete the Hajj and \'umrah for Allah. But if you are prevented, then [offer] what can be obtained with ease of sacrificial animals. And do not shave your heads until the sacrificial animal has reached its place of slaughter. And whoever among you is ill or has an ailment of the head [making shaving necessary must offer] a ransom of fasting [three days] or charity or sacrifice. And when you are secure, then whoever performs \'umrah [during the Hajj months] followed by Hajj [offers] what can be obtained with ease of sacrificial animals. And whoever cannot find [or afford such an animal] - then a fast of three days during Hajj and of seven when you have returned [home]. Those are ten complete [days]. This is for those whose family is not in the area of al-Masjid al-Haram. And fear Allah and know that Allah is severe in penalty.' },
  { surahId: 2, ayahNumber: 197, text: 'Hajj is [during] well-known months, so whoever has made Hajj obligatory upon himself therein [by entering the state of ihram], there is [to be for him] no sexual relations and no disobedience and no disputing during Hajj. And whatever good you do - Allah knows it. And take provisions, but indeed, the best provision is fear of Allah. And fear Me, O you of understanding.' },
  { surahId: 2, ayahNumber: 198, text: 'There is no blame upon you for seeking bounty from your Lord [during Hajj]. But when you depart from \'Arafat, remember Allah at al- Mash\'ar al-Haram. And remember Him, as He has guided you, for indeed, you were before that among those astray.' },
  { surahId: 2, ayahNumber: 199, text: 'Then depart from the place from where [all] the people depart and ask forgiveness of Allah. Indeed, Allah is Forgiving and Merciful.' },
  { surahId: 2, ayahNumber: 200, text: 'And when you have completed your rites, remember Allah like your [previous] remembrance of your fathers or with [much] greater remembrance. And among the people is he who says, "Our Lord, give us in this world," and he will have in the Hereafter no share.' },
  { surahId: 2, ayahNumber: 201, text: 'But among them is he who says, "Our Lord, give us in this world [that which is] good and in the Hereafter [that which is] good and protect us from the punishment of the Fire."' },
  { surahId: 2, ayahNumber: 202, text: 'Those will have a share of what they have earned, and Allah is swift in account.' },
  { surahId: 2, ayahNumber: 203, text: 'And remember Allah during [specific] numbered days. Then whoever hastens [his departure] in two days - there is no sin upon him; and whoever delays [until the third] - there is no sin upon him - for him who fears Allah. And fear Allah and know that unto Him you will be gathered.' },
  { surahId: 2, ayahNumber: 204, text: 'And of the people is he whose speech pleases you in worldly life, and he calls Allah to witness as to what is in his heart, yet he is the fiercest of opponents.' },
  { surahId: 2, ayahNumber: 205, text: 'And when he goes away, he strives throughout the land to cause corruption therein and destroy crops and animals. And Allah does not like corruption.' },
  { surahId: 2, ayahNumber: 206, text: 'And when it is said to him, "Fear Allah," pride in the sin takes hold of him. Sufficient for him is Hellfire, and how wretched is the resting place.' },
  { surahId: 2, ayahNumber: 207, text: 'And of the people is he who sells himself, seeking means to the approval of Allah. And Allah is kind to [His] servants.' },
  { surahId: 2, ayahNumber: 208, text: 'O you who have believed, enter into Islam completely [and perfectly] and do not follow the footsteps of Satan. Indeed, he is to you a clear enemy.' },
  { surahId: 2, ayahNumber: 209, text: 'But if you deviate after clear proofs have come to you, then know that Allah is Exalted in Might and Wise.' },
  { surahId: 2, ayahNumber: 210, text: 'Do they await but that Allah should come to them in covers of clouds and the angels [as well] and the matter is [then] decided? And to Allah [all] matters are returned.' },
  { surahId: 2, ayahNumber: 211, text: 'Ask the Children of Israel how many a sign of evidence We have given them. And whoever exchanges the favor of Allah [for disbelief] after it has come to him - then indeed, Allah is severe in penalty.' },
  { surahId: 2, ayahNumber: 212, text: 'Beautified for those who disbelieve is the life of this world, and they ridicule those who believe. But those who fear Allah are above them on the Day of Resurrection. And Allah gives provision to whom He wills without account.' },
  { surahId: 2, ayahNumber: 213, text: 'Mankind was [of] one religion [before their deviation]; then Allah sent the prophets as bringers of good tidings and warners and sent down with them the Scripture in truth to judge between the people concerning that in which they differed. And none differed over the Scripture except those who were given it - after the clear proofs came to them - out of jealous animosity among themselves. And Allah guided those who believed to the truth concerning that over which they had differed, by His permission. And Allah guides whom He wills to a straight path.' },
  { surahId: 2, ayahNumber: 214, text: 'Or do you think that you will enter Paradise while such [trial] has not yet come to you as came to those who passed on before you? They were touched by poverty and hardship and were shaken until [even their] messenger and those who believed with him said, "When is the help of Allah?" Unquestionably, the help of Allah is near.' },
  { surahId: 2, ayahNumber: 215, text: 'They ask you, [O Muhammad], what they should spend. Say, "Whatever you spend of good is [to be] for parents and relatives and orphans and the needy and the traveler. And whatever you do of good - indeed, Allah is Knowing of it."' },
  { surahId: 2, ayahNumber: 216, text: 'Fighting has been enjoined upon you while it is hateful to you. But perhaps you hate a thing and it is good for you; and perhaps you love a thing and it is bad for you. And Allah Knows, while you know not.' },
  { surahId: 2, ayahNumber: 217, text: 'They ask you about the sacred month - about fighting therein. Say, "Fighting therein is great [sin], but averting [people] from the way of Allah and disbelief in Him and [preventing access to] al-Masjid al-Haram and the expulsion of its people therefrom are greater [evil] in the sight of Allah. And fitnah is greater than killing." And they will continue to fight you until they turn you back from your religion if they are able. And whoever of you reverts from his religion [to disbelief] and dies while he is a disbeliever - for those, their deeds have become worthless in this world and the Hereafter, and those are the companions of the Fire, they will abide therein eternally.' },
  { surahId: 2, ayahNumber: 218, text: 'Indeed, those who have believed and those who have emigrated and fought in the cause of Allah - those expect the mercy of Allah. And Allah is Forgiving and Merciful.' },
  { surahId: 2, ayahNumber: 219, text: 'They ask you about wine and gambling. Say, "In them is great sin and [yet, some] benefit for people. But their sin is greater than their benefit." And they ask you what they should spend. Say, "The excess [beyond needs]." Thus Allah makes clear to you the verses [of revelation] that you might give thought.' },
  { surahId: 2, ayahNumber: 220, text: 'To this world and the Hereafter. And they ask you about orphans. Say, "Improvement for them is best. And if you mix your affairs with theirs - they are your brothers. And Allah knows the corrupter from the amender. And if Allah had willed, He could have put you in difficulty. Indeed, Allah is Exalted in Might and Wise.' },
  { surahId: 2, ayahNumber: 221, text: 'And do not marry polytheistic women until they believe. And a believing slave woman is better than a polytheist, even though she might please you. And do not marry polytheistic men [to your women] until they believe. And a believing slave is better than a polytheist, even though he might please you. Those invite [you] to the Fire, but Allah invites to Paradise and to forgiveness, by His permission. And He makes clear His verses to the people that perhaps they may remember.' },
  { surahId: 2, ayahNumber: 222, text: 'And they ask you about menstruation. Say, "It is harm, so keep away from wives during menstruation. And do not approach them until they are pure. And when they have purified themselves, then come to them from where Allah has ordained for you. Indeed, Allah loves those who are constantly repentant and loves those who purify themselves."' },
  { surahId: 2, ayahNumber: 223, text: 'Your wives are a place of sowing of seed for you, so come to your place of cultivation however you wish and put forth [righteousness] for yourselves. And fear Allah and know that you will meet Him. And give good tidings to the believers.' },
  { surahId: 2, ayahNumber: 224, text: 'And do not make [your oath by] Allah an excuse against being righteous and fearing Allah and making peace among people. And Allah is Hearing and Knowing.' },
  { surahId: 2, ayahNumber: 225, text: 'Allah does not impose blame upon you for what is unintentional in your oaths, but He imposes blame upon you for what your hearts have earned. And Allah is Forgiving and Forbearing.' },
  { surahId: 2, ayahNumber: 226, text: 'For those who swear not to have sexual relations with their wives is a waiting time of four months, but if they return [to normal relations] - then indeed, Allah is Forgiving and Merciful.' },
  { surahId: 2, ayahNumber: 227, text: 'And if they decide on divorce - then indeed, Allah is Hearing and Knowing.' },
  { surahId: 2, ayahNumber: 228, text: 'Divorced women remain in waiting for three periods, and it is not lawful for them to conceal what Allah has created in their wombs if they believe in Allah and the Last Day. And their husbands have more right to take them back in this [period] if they want reconciliation. And due to the wives is similar to what is expected of them, according to what is reasonable. But the men have a degree over them [in responsibility and authority]. And Allah is Exalted in Might and Wise.' },
  { surahId: 2, ayahNumber: 229, text: 'Divorce is twice. Then, either keep [her] in an acceptable manner or release [her] with good treatment. And it is not lawful for you to take anything of what you have given them unless both fear that they will not be able to keep [within] the limits of Allah. But if you fear that they will not keep [within] the limits of Allah, then there is no blame upon either of them concerning that by which she ransoms herself. These are the limits of Allah, so do not transgress them. And whoever transgresses the limits of Allah - it is those who are the wrongdoers.' },
  { surahId: 2, ayahNumber: 230, text: 'And if he has divorced her [for the third time], then she is not lawful to him afterward until [after] she marries a husband other than him. And if the latter husband divorces her [or dies], there is no blame upon the woman and her former husband for returning to each other if they think that they can keep [within] the limits of Allah. These are the limits of Allah, which He makes clear to a people who know.' },
  { surahId: 2, ayahNumber: 231, text: 'And when you divorce women and they have [nearly] fulfilled their term, either retain them according to acceptable terms or release them according to acceptable terms, and do not keep them, intending harm, to transgress [against them]. And whoever does that has certainly wronged himself. And do not take the verses of Allah in jest. And remember the favor of Allah upon you and what has been revealed to you of the Book and wisdom by which He instructs you. And fear Allah and know that Allah is Knowing of all things.' },
  { surahId: 2, ayahNumber: 232, text: 'And when you divorce women and they have fulfilled their term, do not prevent them from remarrying their [former] husbands if they agree among themselves on an acceptable basis. That is instructed to whoever of you believes in Allah and the Last Day. That is better for you and purer, and Allah knows and you know not.' },
  { surahId: 2, ayahNumber: 233, text: 'Mothers may breastfeed their children two complete years for whoever wishes to complete the nursing [period]. Upon the father is the mothers\' provision and their clothing according to what is acceptable. No person is charged with more than his capacity. No mother should be harmed through her child, and no father through his child. And upon the [father\'s] heir is [a duty] like that [of the father]. And if they both desire weaning through mutual consent from both of them and consultation, there is no blame upon either of them. And if you wish to have your children nursed by a substitute, there is no blame upon you as long as you give payment according to what is acceptable. And fear Allah and know that Allah is Seeing of what you do.' },
  { surahId: 2, ayahNumber: 234, text: 'And those who are taken in death among you and leave wives behind - they, [the wives, shall] wait four months and ten [days]. And when they have fulfilled their term, then there is no blame upon you for what they do with themselves in an acceptable manner. And Allah is [fully] Acquainted with what you do.' },
  { surahId: 2, ayahNumber: 235, text: 'There is no blame upon you for that to which you [indirectly] allude concerning a proposal to women or for what you conceal within yourselves. Allah knows that you will have them in mind. But do not promise them secretly except for saying a proper saying. And do not determine to undertake a marriage contract until the decreed period reaches its end. And know that Allah knows what is within yourselves, so beware of Him. And know that Allah is Forgiving and Forbearing.' },
  { surahId: 2, ayahNumber: 236, text: 'There is no blame upon you if you divorce women you have not touched nor specified for them an obligation. But give them [a gift of] compensation - the wealthy according to his capability and the poor according to his capability - a provision according to what is acceptable, a duty upon the doers of good.' },
  { surahId: 2, ayahNumber: 237, text: 'And if you divorce them before you have touched them and you have already specified for them an obligation, then [give] half of what you specified - unless they forego the right or the one in whose hand is the marriage contract foregoes it. And to forego it is nearer to righteousness. And do not forget graciousness between you. Indeed Allah, of whatever you do, is Seeing.' },
  { surahId: 2, ayahNumber: 238, text: 'Maintain with care the [obligatory] prayers and [in particular] the middle prayer and stand before Allah, devoutly obedient.' },
  { surahId: 2, ayahNumber: 239, text: 'And if you fear [an enemy, then pray] on foot or riding. But when you are secure, then remember Allah [in prayer], as He has taught you that which you did not [previously] know.' },
  { surahId: 2, ayahNumber: 240, text: 'And those who are taken in death among you and leave wives behind - for their wives is a bequest: maintenance for one year without turning [them] out. But if they leave [of their own accord], then there is no blame upon you for what they do with themselves in an acceptable way. And Allah is Exalted in Might and Wise.' },
  { surahId: 2, ayahNumber: 241, text: 'And for divorced women is a provision according to what is acceptable - a duty upon the righteous.' },
  { surahId: 2, ayahNumber: 242, text: 'Thus does Allah make clear to you His verses that you might use reason.' },
  { surahId: 2, ayahNumber: 243, text: 'Have you not considered those who left their homes in many thousands, fearing death? Allah said to them, "Die"; then He restored them to life. And Allah is full of bounty to the people, but most of the people do not show gratitude.' },
  { surahId: 2, ayahNumber: 244, text: 'And fight in the cause of Allah and know that Allah is Hearing and Knowing.' },
  { surahId: 2, ayahNumber: 245, text: 'Who is it that would loan Allah a goodly loan so He may multiply it for him many times over? And it is Allah who withholds and grants abundance, and to Him you will be returned.' },
  { surahId: 2, ayahNumber: 246, text: 'Have you not considered the assembly of the Children of Israel after [the time of] Moses when they said to a prophet of theirs, "Send to us a king, and we will fight in the way of Allah "? He said, "Would you perhaps refrain from fighting if fighting was prescribed for you?" They said, "And why should we not fight in the cause of Allah when we have been driven out from our homes and from our children?" But when fighting was prescribed for them, they turned away, except for a few of them. And Allah is Knowing of the wrongdoers.' },
  { surahId: 2, ayahNumber: 247, text: 'And their prophet said to them, "Indeed, Allah has sent to you Saul as a king." They said, "How can he have kingship over us while we are more worthy of kingship than him and he has not been given any measure of wealth?" He said, "Indeed, Allah has chosen him over you and has increased him abundantly in knowledge and stature. And Allah gives His sovereignty to whom He wills. And Allah is all-Encompassing [in favor] and Knowing."' },
  { surahId: 2, ayahNumber: 248, text: 'And their prophet said to them, "Indeed, a sign of his kingship is that the chest will come to you in which is assurance from your Lord and a remnant of what the family of Moses and the family of Aaron had left, carried by the angels. Indeed in that is a sign for you, if you are believers."' },
  { surahId: 2, ayahNumber: 249, text: 'And when Saul went forth with the soldiers, he said, "Indeed, Allah will be testing you with a river. So whoever drinks from it is not of me, and whoever does not taste it is indeed of me, excepting one who takes [from it] in the hollow of his hand." But they drank from it, except a [very] few of them. Then when he had crossed it along with those who believed with him, they said, "There is no power for us today against Goliath and his soldiers." But those who were certain that they would meet Allah said, "How many a small company has overcome a large company by permission of Allah. And Allah is with the patient."' },
  { surahId: 2, ayahNumber: 250, text: 'And when they went forth to [face] Goliath and his soldiers, they said, "Our Lord, pour upon us patience and plant firmly our feet and give us victory over the disbelieving people."' },
  { surahId: 2, ayahNumber: 251, text: 'So they defeated them by permission of Allah, and David killed Goliath, and Allah gave him the kingship and prophethood and taught him from that which He willed. And if it were not for Allah checking [some] people by means of others, the earth would have been corrupted, but Allah is full of bounty to the worlds.' },
  { surahId: 2, ayahNumber: 252, text: 'These are the verses of Allah which We recite to you, [O Muhammad], in truth. And indeed, you are from among the messengers.' },
  { surahId: 2, ayahNumber: 253, text: 'Those messengers - some of them We caused to exceed others. Among them were those to whom Allah spoke, and He raised some of them in degree. And We gave Jesus, the Son of Mary, clear proofs, and We supported him with the Pure Spirit. If Allah had willed, those [generations] succeeding them would not have fought each other after the clear proofs had come to them. But they differed, and some of them believed and some of them disbelieved. And if Allah had willed, they would not have fought each other, but Allah does what He intends.' },
  { surahId: 2, ayahNumber: 254, text: 'O you who have believed, spend from that which We have provided for you before there comes a Day in which there is no exchange and no friendship and no intercession. And the disbelievers - they are the wrongdoers.' },
  { surahId: 2, ayahNumber: 255, text: 'Allah - there is no deity except Him, the Ever-Living, the Sustainer of [all] existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is [presently] before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.' },
  { surahId: 2, ayahNumber: 256, text: 'There shall be no compulsion in [acceptance of] the religion. The right course has become clear from the wrong. So whoever disbelieves in Taghut and believes in Allah has grasped the most trustworthy handhold with no break in it. And Allah is Hearing and Knowing.' },
  { surahId: 2, ayahNumber: 257, text: 'Allah is the ally of those who believe. He brings them out from darknesses into the light. And those who disbelieve - their allies are Taghut. They take them out of the light into darknesses. Those are the companions of the Fire; they will abide eternally therein.' },
  { surahId: 2, ayahNumber: 258, text: 'Have you not considered the one who argued with Abraham about his Lord [merely] because Allah had given him kingship? When Abraham said, "My Lord is the one who gives life and causes death," he said, "I give life and cause death." Abraham said, "Indeed, Allah brings up the sun from the east, so bring it up from the west." So the disbeliever was overwhelmed [by astonishment], and Allah does not guide the wrongdoing people.' },
  { surahId: 2, ayahNumber: 259, text: 'Or [consider such an example] as the one who passed by a township which had fallen into ruin. He said, "How will Allah bring this to life after its death?" So Allah caused him to die for a hundred years; then He revived him. He said, "How long have you remained?" The man said, "I have remained a day or part of a day." He said, "Rather, you have remained one hundred years. Look at your food and your drink; it has not changed with time. And look at your donkey; and We will make you a sign for the people. And look at the bones [of this donkey] - how We raise them and then We cover them with flesh." And when it became clear to him, he said, "I know that Allah is over all things competent."' },
  { surahId: 2, ayahNumber: 260, text: 'And [mention] when Abraham said, "My Lord, show me how You give life to the dead." [Allah] said, "Have you not believed?" He said, "Yes, but [I ask] only that my heart may be satisfied." [Allah] said, "Take four birds and commit them to yourself. Then [after slaughtering them] put on each hill a portion of them; then call them - they will come [flying] to you in haste. And know that Allah is Exalted in Might and Wise."' },
  { surahId: 2, ayahNumber: 261, text: 'The example of those who spend their wealth in the way of Allah is like a seed [of grain] which grows seven spikes; in each spike is a hundred grains. And Allah multiplies [His reward] for whom He wills. And Allah is all-Encompassing and Knowing.' },
  { surahId: 2, ayahNumber: 262, text: 'Those who spend their wealth in the way of Allah and then do not follow up what they have spent with reminders [of it] or [other] injury will have their reward with their Lord, and there will be no fear concerning them, nor will they grieve.' },
  { surahId: 2, ayahNumber: 263, text: 'Kind speech and forgiveness are better than charity followed by injury. And Allah is Free of need and Forbearing.' },
  { surahId: 2, ayahNumber: 264, text: 'O you who have believed, do not invalidate your charities with reminders or injury as does one who spends his wealth [only] to be seen by the people and does not believe in Allah and the Last Day. His example is like that of a [large] smooth stone upon which is dust and is hit by a downpour that leaves it bare. They are unable [to keep] anything of what they have earned. And Allah does not guide the disbelieving people.' },
  { surahId: 2, ayahNumber: 265, text: 'And the example of those who spend their wealth seeking means to the approval of Allah and assuring [reward for] themselves is like a garden on high ground which is hit by a downpour - so it yields its fruits in double. And [even] if it is not hit by a downpour, then a drizzle [is sufficient]. And Allah, of what you do, is Seeing.' },
  { surahId: 2, ayahNumber: 266, text: 'Would one of you like to have a garden of palm trees and grapevines underneath which rivers flow in which he has from every fruit? But he is afflicted with old age and has weak offspring, and it is hit by a whirlwind containing fire and is burned. Thus does Allah make clear to you [His] verses that you might give thought.' },
  { surahId: 2, ayahNumber: 267, text: 'O you who have believed, spend from the good things which you have earned and from that which We have produced for you from the earth. And do not aim toward the defective therefrom, spending [from that] while you would not take it [yourself] except with closed eyes. And know that Allah is Free of need and Praiseworthy.' },
  { surahId: 2, ayahNumber: 268, text: 'Satan threatens you with poverty and orders you to immorality, while Allah promises you forgiveness from Him and bounty. And Allah is all-Encompassing and Knowing.' },
  { surahId: 2, ayahNumber: 269, text: 'He gives wisdom to whom He wills, and whoever has been given wisdom has certainly been given much good. And none will remember except those of understanding.' },
  { surahId: 2, ayahNumber: 270, text: 'And whatever you spend of expenditures or make of vows - indeed, Allah knows of it. And for the wrongdoers there are no helpers.' },
  { surahId: 2, ayahNumber: 271, text: 'If you disclose your charitable expenditures, they are good; but if you conceal them and give them to the poor, it is better for you, and He will remove from you some of your misdeeds [thereby]. And Allah, with what you do, is [fully] Acquainted.' },
  { surahId: 2, ayahNumber: 272, text: 'Not upon you, [O Muhammad], is [responsibility for] their guidance, but Allah guides whom He wills. And whatever good you [believers] spend is for yourselves, and you do not spend except seeking the countenance of Allah. And whatever you spend of good - it will be fully repaid to you, and you will not be wronged.' },
  { surahId: 2, ayahNumber: 273, text: '[Charity is] for the poor who have been restricted for the cause of Allah, unable to move about in the land. An ignorant [person] would think them self-sufficient because of their restraint, but you will know them by their [characteristic] sign. They do not ask people persistently [or at all]. And whatever you spend of good - indeed, Allah is Knowing of it.' },
  { surahId: 2, ayahNumber: 274, text: 'Those who spend their wealth [in Allah \'s way] by night and by day, secretly and publicly - they will have their reward with their Lord. And no fear will there be concerning them, nor will they grieve.' },
  { surahId: 2, ayahNumber: 275, text: 'Those who consume interest cannot stand [on the Day of Resurrection] except as one stands who is being beaten by Satan into insanity. That is because they say, "Trade is [just] like interest." But Allah has permitted trade and has forbidden interest. So whoever has received an admonition from his Lord and desists may have what is past, and his affair rests with Allah. But whoever returns to [dealing in interest or usury] - those are the companions of the Fire; they will abide eternally therein.' },
  { surahId: 2, ayahNumber: 276, text: 'Allah destroys interest and gives increase for charities. And Allah does not like every sinning disbeliever.' },
  { surahId: 2, ayahNumber: 277, text: 'Indeed, those who believe and do righteous deeds and establish prayer and give zakah will have their reward with their Lord, and there will be no fear concerning them, nor will they grieve.' },
  { surahId: 2, ayahNumber: 278, text: 'O you who have believed, fear Allah and give up what remains [due to you] of interest, if you should be believers.' },
  { surahId: 2, ayahNumber: 279, text: 'And if you do not, then be informed of a war [against you] from Allah and His Messenger. But if you repent, you may have your principal - [thus] you do no wrong, nor are you wronged.' },
  { surahId: 2, ayahNumber: 280, text: 'And if someone is in hardship, then [let there be] postponement until [a time of] ease. But if you give [from your right as] charity, then it is better for you, if you only knew.' },
  { surahId: 2, ayahNumber: 281, text: 'And fear a Day when you will be returned to Allah. Then every soul will be compensated for what it earned, and they will not be treated unjustly.' },
  { surahId: 2, ayahNumber: 282, text: 'O you who have believed, when you contract a debt for a specified term, write it down. And let a scribe write [it] between you in justice. Let no scribe refuse to write as Allah has taught him. So let him write and let the one who has the obligation dictate. And let him fear Allah, his Lord, and not leave anything out of it. But if the one who has the obligation is of limited understanding or weak or unable to dictate himself, then let his guardian dictate in justice. And bring to witness two witnesses from among your men. And if there are not two men [available], then a man and two women from those whom you accept as witnesses - so that if one of the women errs, then the other can remind her. And let not the witnesses refuse when they are called upon. And do not be [too] weary to write it, whether it is small or large, for its [specified] term. That is more just in the sight of Allah and stronger as evidence and more likely to prevent doubt between you, except when it is an immediate transaction which you conduct among yourselves. For [then] there is no blame upon you if you do not write it. And take witnesses when you conclude a contract. Let no scribe be harmed or any witness. For if you do so, indeed, it is [grave] disobedience in you. And fear Allah. And Allah teaches you. And Allah is Knowing of all things.' },
  { surahId: 2, ayahNumber: 283, text: 'And if you are on a journey and cannot find a scribe, then a security deposit [should be] taken. And if one of you entrusts another, then let him who is entrusted discharge his trust [faithfully] and let him fear Allah, his Lord. And do not conceal testimony, for whoever conceals it - his heart is indeed sinful, and Allah is Knowing of what you do.' },
  { surahId: 2, ayahNumber: 284, text: 'To Allah belongs whatever is in the heavens and whatever is in the earth. Whether you show what is within yourselves or conceal it, Allah will bring you to account for it. Then He will forgive whom He wills and punish whom He wills, and Allah is over all things competent.' },
  { surahId: 2, ayahNumber: 285, text: 'The Messenger has believed in what was revealed to him from his Lord, and [so have] the believers. All of them have believed in Allah and His angels and His books and His messengers, [saying], "We make no distinction between any of His messengers." And they say, "We hear and we obey. [We seek] Your forgiveness, our Lord, and to You is the [final] destination."' },
  { surahId: 2, ayahNumber: 286, text: 'Allah does not charge a soul except [with that within] its capacity. It will have [the consequence of] what [good] it has gained, and it will bear [the consequence of] what [evil] it has earned. "Our Lord, do not impose blame upon us if we have forgotten or erred. Our Lord, and lay not upon us a burden like that which You laid upon those before us. Our Lord, and burden us not with that which we have no ability to bear. And pardon us; and forgive us; and have mercy upon us. You are our protector, so give us victory over the disbelieving people."' },
  { surahId: 3, ayahNumber: 1, text: 'Alif, Lam, Meem.' },
  { surahId: 3, ayahNumber: 2, text: 'Allah - there is no deity except Him, the Ever-Living, the Sustainer of existence.' },
  { surahId: 3, ayahNumber: 3, text: 'He has sent down upon you, [O Muhammad], the Book in truth, confirming what was before it. And He revealed the Torah and the Gospel.' },
  { surahId: 3, ayahNumber: 4, text: 'Before, as guidance for the people. And He revealed the Qur\'an. Indeed, those who disbelieve in the verses of Allah will have a severe punishment, and Allah is exalted in Might, the Owner of Retribution.' },
  { surahId: 3, ayahNumber: 5, text: 'Indeed, from Allah nothing is hidden in the earth nor in the heaven.' },
  { surahId: 3, ayahNumber: 6, text: 'It is He who forms you in the wombs however He wills. There is no deity except Him, the Exalted in Might, the Wise.' },
  { surahId: 3, ayahNumber: 7, text: 'It is He who has sent down to you, [O Muhammad], the Book; in it are verses [that are] precise - they are the foundation of the Book - and others unspecific. As for those in whose hearts is deviation [from truth], they will follow that of it which is unspecific, seeking discord and seeking an interpretation [suitable to them]. And no one knows its [true] interpretation except Allah. But those firm in knowledge say, "We believe in it. All [of it] is from our Lord." And no one will be reminded except those of understanding.' },
  { surahId: 3, ayahNumber: 8, text: '[Who say], "Our Lord, let not our hearts deviate after You have guided us and grant us from Yourself mercy. Indeed, You are the Bestower.' },
  { surahId: 3, ayahNumber: 9, text: 'Our Lord, surely You will gather the people for a Day about which there is no doubt. Indeed, Allah does not fail in His promise."' },
  { surahId: 3, ayahNumber: 10, text: 'Indeed, those who disbelieve - never will their wealth or their children avail them against Allah at all. And it is they who are fuel for the Fire.' },
  { surahId: 3, ayahNumber: 11, text: '[Theirs is] like the custom of the people of Pharaoh and those before them. They denied Our signs, so Allah seized them for their sins. And Allah is severe in penalty.' },
  { surahId: 3, ayahNumber: 12, text: 'Say to those who disbelieve, "You will be overcome and gathered together to Hell, and wretched is the resting place."' },
  { surahId: 3, ayahNumber: 13, text: 'Already there has been for you a sign in the two armies which met - one fighting in the cause of Allah and another of disbelievers. They saw them [to be] twice their [own] number by [their] eyesight. But Allah supports with His victory whom He wills. Indeed in that is a lesson for those of vision.' },
  { surahId: 3, ayahNumber: 14, text: 'Beautified for people is the love of that which they desire - of women and sons, heaped-up sums of gold and silver, fine branded horses, and cattle and tilled land. That is the enjoyment of worldly life, but Allah has with Him the best return.' },
  { surahId: 3, ayahNumber: 15, text: 'Say, "Shall I inform you of [something] better than that? For those who fear Allah will be gardens in the presence of their Lord beneath which rivers flow, wherein they abide eternally, and purified spouses and approval from Allah. And Allah is Seeing of [His] servants -' },
  { surahId: 3, ayahNumber: 16, text: 'Those who say, "Our Lord, indeed we have believed, so forgive us our sins and protect us from the punishment of the Fire,"' },
  { surahId: 3, ayahNumber: 17, text: 'The patient, the true, the obedient, those who spend [in the way of Allah], and those who seek forgiveness before dawn.' },
  { surahId: 3, ayahNumber: 18, text: 'Allah witnesses that there is no deity except Him, and [so do] the angels and those of knowledge - [that He is] maintaining [creation] in justice. There is no deity except Him, the Exalted in Might, the Wise.' },
  { surahId: 3, ayahNumber: 19, text: 'Indeed, the religion in the sight of Allah is Islam. And those who were given the Scripture did not differ except after knowledge had come to them - out of jealous animosity between themselves. And whoever disbelieves in the verses of Allah, then indeed, Allah is swift in [taking] account.' },
  { surahId: 3, ayahNumber: 20, text: 'So if they argue with you, say, "I have submitted myself to Allah [in Islam], and [so have] those who follow me." And say to those who were given the Scripture and [to] the unlearned, "Have you submitted yourselves?" And if they submit [in Islam], they are rightly guided; but if they turn away - then upon you is only the [duty of] notification. And Allah is Seeing of [His] servants.' },
  { surahId: 3, ayahNumber: 21, text: 'Those who disbelieve in the signs of Allah and kill the prophets without right and kill those who order justice from among the people - give them tidings of a painful punishment.' },
  { surahId: 3, ayahNumber: 22, text: 'They are the ones whose deeds have become worthless in this world and the Hereafter, and for them there will be no helpers.' },
  { surahId: 3, ayahNumber: 23, text: 'Do you not consider, [O Muhammad], those who were given a portion of the Scripture? They are invited to the Scripture of Allah that it should arbitrate between them; then a party of them turns away, and they are refusing.' },
  { surahId: 3, ayahNumber: 24, text: 'That is because they say, "Never will the Fire touch us except for [a few] numbered days," and [because] they were deluded in their religion by what they were inventing.' },
  { surahId: 3, ayahNumber: 25, text: 'So how will it be when We assemble them for a Day about which there is no doubt? And each soul will be compensated [in full for] what it earned, and they will not be wronged.' },
  { surahId: 3, ayahNumber: 26, text: 'Say, "O Allah, Owner of Sovereignty, You give sovereignty to whom You will and You take sovereignty away from whom You will. You honor whom You will and You humble whom You will. In Your hand is [all] good. Indeed, You are over all things competent.' },
  { surahId: 3, ayahNumber: 27, text: 'You cause the night to enter the day, and You cause the day to enter the night; and You bring the living out of the dead, and You bring the dead out of the living. And You give provision to whom You will without account."' },
  { surahId: 3, ayahNumber: 28, text: 'Let not believers take disbelievers as allies rather than believers. And whoever [of you] does that has nothing with Allah, except when taking precaution against them in prudence. And Allah warns you of Himself, and to Allah is the [final] destination.' },
  { surahId: 3, ayahNumber: 29, text: 'Say, "Whether you conceal what is in your breasts or reveal it, Allah knows it. And He knows that which is in the heavens and that which is on the earth. And Allah is over all things competent.' },
  { surahId: 3, ayahNumber: 30, text: 'The Day every soul will find what it has done of good present [before it] and what it has done of evil, it will wish that between itself and that [evil] was a great distance. And Allah warns you of Himself, and Allah is Kind to [His] servants."' },
  { surahId: 3, ayahNumber: 31, text: 'Say, [O Muhammad], "If you should love Allah, then follow me, [so] Allah will love you and forgive you your sins. And Allah is Forgiving and Merciful."' },
  { surahId: 3, ayahNumber: 32, text: 'Say, "Obey Allah and the Messenger." But if they turn away - then indeed, Allah does not like the disbelievers.' },
  { surahId: 3, ayahNumber: 33, text: 'Indeed, Allah chose Adam and Noah and the family of Abraham and the family of \'Imran over the worlds -' },
  { surahId: 3, ayahNumber: 34, text: 'Descendants, some of them from others. And Allah is Hearing and Knowing.' },
  { surahId: 3, ayahNumber: 35, text: '[Mention, O Muhammad], when the wife of \'Imran said, "My Lord, indeed I have pledged to You what is in my womb, consecrated [for Your service], so accept this from me. Indeed, You are the Hearing, the Knowing."' },
  { surahId: 3, ayahNumber: 36, text: 'But when she delivered her, she said, "My Lord, I have delivered a female." And Allah was most knowing of what she delivered, "And the male is not like the female. And I have named her Mary, and I seek refuge for her in You and [for] her descendants from Satan, the expelled [from the mercy of Allah]."' },
  { surahId: 3, ayahNumber: 37, text: 'So her Lord accepted her with good acceptance and caused her to grow in a good manner and put her in the care of Zechariah. Every time Zechariah entered upon her in the prayer chamber, he found with her provision. He said, "O Mary, from where is this [coming] to you?" She said, "It is from Allah. Indeed, Allah provides for whom He wills without account."' },
  { surahId: 3, ayahNumber: 38, text: 'At that, Zechariah called upon his Lord, saying, "My Lord, grant me from Yourself a good offspring. Indeed, You are the Hearer of supplication."' },
  { surahId: 3, ayahNumber: 39, text: 'So the angels called him while he was standing in prayer in the chamber, "Indeed, Allah gives you good tidings of John, confirming a word from Allah and [who will be] honorable, abstaining [from women], and a prophet from among the righteous."' },
  { surahId: 3, ayahNumber: 40, text: 'He said, "My Lord, how will I have a boy when I have reached old age and my wife is barren?" The angel said, "Such is Allah; He does what He wills."' },
  { surahId: 3, ayahNumber: 41, text: 'He said, "My Lord, make for me a sign." He Said, "Your sign is that you will not [be able to] speak to the people for three days except by gesture. And remember your Lord much and exalt [Him with praise] in the evening and the morning."' },
  { surahId: 3, ayahNumber: 42, text: 'And [mention] when the angels said, "O Mary, indeed Allah has chosen you and purified you and chosen you above the women of the worlds.' },
  { surahId: 3, ayahNumber: 43, text: 'O Mary, be devoutly obedient to your Lord and prostrate and bow with those who bow [in prayer]."' },
  { surahId: 3, ayahNumber: 44, text: 'That is from the news of the unseen which We reveal to you, [O Muhammad]. And you were not with them when they cast their pens as to which of them should be responsible for Mary. Nor were you with them when they disputed.' },
  { surahId: 3, ayahNumber: 45, text: '[And mention] when the angels said, "O Mary, indeed Allah gives you good tidings of a word from Him, whose name will be the Messiah, Jesus, the son of Mary - distinguished in this world and the Hereafter and among those brought near [to Allah].' },
  { surahId: 3, ayahNumber: 46, text: 'He will speak to the people in the cradle and in maturity and will be of the righteous."' },
  { surahId: 3, ayahNumber: 47, text: 'She said, "My Lord, how will I have a child when no man has touched me?" [The angel] said, "Such is Allah; He creates what He wills. When He decrees a matter, He only says to it, \'Be,\' and it is.' },
  { surahId: 3, ayahNumber: 48, text: 'And He will teach him writing and wisdom and the Torah and the Gospel' },
  { surahId: 3, ayahNumber: 49, text: 'And [make him] a messenger to the Children of Israel, [who will say], \'Indeed I have come to you with a sign from your Lord in that I design for you from clay [that which is] like the form of a bird, then I breathe into it and it becomes a bird by permission of Allah. And I cure the blind and the leper, and I give life to the dead - by permission of Allah. And I inform you of what you eat and what you store in your houses. Indeed in that is a sign for you, if you are believers.' },
  { surahId: 3, ayahNumber: 50, text: 'And [I have come] confirming what was before me of the Torah and to make lawful for you some of what was forbidden to you. And I have come to you with a sign from your Lord, so fear Allah and obey me.' },
  { surahId: 3, ayahNumber: 51, text: 'Indeed, Allah is my Lord and your Lord, so worship Him. That is the straight path."' },
  { surahId: 3, ayahNumber: 52, text: 'But when Jesus felt [persistence in] disbelief from them, he said, "Who are my supporters for [the cause of] Allah?" The disciples said, "We are supporters for Allah. We have believed in Allah and testify that we are Muslims [submitting to Him].' },
  { surahId: 3, ayahNumber: 53, text: 'Our Lord, we have believed in what You revealed and have followed the messenger Jesus, so register us among the witnesses [to truth]."' },
  { surahId: 3, ayahNumber: 54, text: 'And the disbelievers planned, but Allah planned. And Allah is the best of planners.' },
  { surahId: 3, ayahNumber: 55, text: '[Mention] when Allah said, "O Jesus, indeed I will take you and raise you to Myself and purify you from those who disbelieve and make those who follow you [in submission to Allah alone] superior to those who disbelieve until the Day of Resurrection. Then to Me is your return, and I will judge between you concerning that in which you used to differ.' },
  { surahId: 3, ayahNumber: 56, text: 'And as for those who disbelieved, I will punish them with a severe punishment in this world and the Hereafter, and they will have no helpers."' },
  { surahId: 3, ayahNumber: 57, text: 'But as for those who believed and did righteous deeds, He will give them in full their rewards, and Allah does not like the wrongdoers.' },
  { surahId: 3, ayahNumber: 58, text: 'This is what We recite to you, [O Muhammad], of [Our] verses and the precise [and wise] message.' },
  { surahId: 3, ayahNumber: 59, text: 'Indeed, the example of Jesus to Allah is like that of Adam. He created Him from dust; then He said to him, "Be," and he was.' },
  { surahId: 3, ayahNumber: 60, text: 'The truth is from your Lord, so do not be among the doubters.' },
  { surahId: 3, ayahNumber: 61, text: 'Then whoever argues with you about it after [this] knowledge has come to you - say, "Come, let us call our sons and your sons, our women and your women, ourselves and yourselves, then supplicate earnestly [together] and invoke the curse of Allah upon the liars [among us]."' },
  { surahId: 3, ayahNumber: 62, text: 'Indeed, this is the true narration. And there is no deity except Allah. And indeed, Allah is the Exalted in Might, the Wise.' },
  { surahId: 3, ayahNumber: 63, text: 'But if they turn away, then indeed - Allah is Knowing of the corrupters.' },
  { surahId: 3, ayahNumber: 64, text: 'Say, "O People of the Scripture, come to a word that is equitable between us and you - that we will not worship except Allah and not associate anything with Him and not take one another as lords instead of Allah." But if they turn away, then say, "Bear witness that we are Muslims [submitting to Him]."' },
  { surahId: 3, ayahNumber: 65, text: 'O People of the Scripture, why do you argue about Abraham while the Torah and the Gospel were not revealed until after him? Then will you not reason?' },
  { surahId: 3, ayahNumber: 66, text: 'Here you are - those who have argued about that of which you have [some] knowledge, but why do you argue about that of which you have no knowledge? And Allah knows, while you know not.' },
  { surahId: 3, ayahNumber: 67, text: 'Abraham was neither a Jew nor a Christian, but he was one inclining toward truth, a Muslim [submitting to Allah]. And he was not of the polytheists.' },
  { surahId: 3, ayahNumber: 68, text: 'Indeed, the most worthy of Abraham among the people are those who followed him [in submission to Allah] and this prophet, and those who believe [in his message]. And Allah is the ally of the believers.' },
  { surahId: 3, ayahNumber: 69, text: 'A faction of the people of the Scripture wish they could mislead you. But they do not mislead except themselves, and they perceive [it] not.' },
  { surahId: 3, ayahNumber: 70, text: 'O People of the Scripture, why do you disbelieve in the verses of Allah while you witness [to their truth]?' },
  { surahId: 3, ayahNumber: 71, text: 'O People of the Scripture, why do you confuse the truth with falsehood and conceal the truth while you know [it]?' },
  { surahId: 3, ayahNumber: 72, text: 'And a faction of the People of the Scripture say [to each other], "Believe in that which was revealed to the believers at the beginning of the day and reject it at its end that perhaps they will abandon their religion,' },
  { surahId: 3, ayahNumber: 73, text: 'And do not trust except those who follow your religion." Say, "Indeed, the [true] guidance is the guidance of Allah. [Do you fear] lest someone be given [knowledge] like you were given or that they would [thereby] argue with you before your Lord?" Say, "Indeed, [all] bounty is in the hand of Allah - He grants it to whom He wills. And Allah is all-Encompassing and Wise."' },
  { surahId: 3, ayahNumber: 74, text: 'He selects for His mercy whom He wills. And Allah is the possessor of great bounty.' },
  { surahId: 3, ayahNumber: 75, text: 'And among the People of the Scripture is he who, if you entrust him with a great amount [of wealth], he will return it to you. And among them is he who, if you entrust him with a [single] silver coin, he will not return it to you unless you are constantly standing over him [demanding it]. That is because they say, "There is no blame upon us concerning the unlearned." And they speak untruth about Allah while they know [it].' },
  { surahId: 3, ayahNumber: 76, text: 'But yes, whoever fulfills his commitment and fears Allah - then indeed, Allah loves those who fear Him.' },
  { surahId: 3, ayahNumber: 77, text: 'Indeed, those who exchange the covenant of Allah and their [own] oaths for a small price will have no share in the Hereafter, and Allah will not speak to them or look at them on the Day of Resurrection, nor will He purify them; and they will have a painful punishment.' },
  { surahId: 3, ayahNumber: 78, text: 'And indeed, there is among them a party who alter the Scripture with their tongues so you may think it is from the Scripture, but it is not from the Scripture. And they say, "This is from Allah," but it is not from Allah. And they speak untruth about Allah while they know.' },
  { surahId: 3, ayahNumber: 79, text: 'It is not for a human [prophet] that Allah should give him the Scripture and authority and prophethood and then he would say to the people, "Be servants to me rather than Allah," but [instead, he would say], "Be pious scholars of the Lord because of what you have taught of the Scripture and because of what you have studied."' },
  { surahId: 3, ayahNumber: 80, text: 'Nor could he order you to take the angels and prophets as lords. Would he order you to disbelief after you had been Muslims?' },
  { surahId: 3, ayahNumber: 81, text: 'And [recall, O People of the Scripture], when Allah took the covenant of the prophets, [saying], "Whatever I give you of the Scripture and wisdom and then there comes to you a messenger confirming what is with you, you [must] believe in him and support him." [Allah] said, "Have you acknowledged and taken upon that My commitment?" They said, "We have acknowledged it." He said, "Then bear witness, and I am with you among the witnesses."' },
  { surahId: 3, ayahNumber: 82, text: 'And whoever turned away after that - they were the defiantly disobedient.' },
  { surahId: 3, ayahNumber: 83, text: 'So is it other than the religion of Allah they desire, while to Him have submitted [all] those within the heavens and earth, willingly or by compulsion, and to Him they will be returned?' },
  { surahId: 3, ayahNumber: 84, text: 'Say, "We have believed in Allah and in what was revealed to us and what was revealed to Abraham, Ishmael, Isaac, Jacob, and the Descendants, and in what was given to Moses and Jesus and to the prophets from their Lord. We make no distinction between any of them, and we are Muslims [submitting] to Him."' },
  { surahId: 3, ayahNumber: 85, text: 'And whoever desires other than Islam as religion - never will it be accepted from him, and he, in the Hereafter, will be among the losers.' },
  { surahId: 3, ayahNumber: 86, text: 'How shall Allah guide a people who disbelieved after their belief and had witnessed that the Messenger is true and clear signs had come to them? And Allah does not guide the wrongdoing people.' },
  { surahId: 3, ayahNumber: 87, text: 'Those - their recompense will be that upon them is the curse of Allah and the angels and the people, all together,' },
  { surahId: 3, ayahNumber: 88, text: 'Abiding eternally therein. The punishment will not be lightened for them, nor will they be reprieved.' },
  { surahId: 3, ayahNumber: 89, text: 'Except for those who repent after that and correct themselves. For indeed, Allah is Forgiving and Merciful.' },
  { surahId: 3, ayahNumber: 90, text: 'Indeed, those who reject the message after their belief and then increase in disbelief - never will their [claimed] repentance be accepted, and they are the ones astray.' },
  { surahId: 3, ayahNumber: 91, text: 'Indeed, those who disbelieve and die while they are disbelievers - never would the [whole] capacity of the earth in gold be accepted from one of them if he would [seek to] ransom himself with it. For those there will be a painful punishment, and they will have no helpers.' },
  { surahId: 3, ayahNumber: 92, text: 'Never will you attain the good [reward] until you spend [in the way of Allah] from that which you love. And whatever you spend - indeed, Allah is Knowing of it.' },
  { surahId: 3, ayahNumber: 93, text: 'All food was lawful to the Children of Israel except what Israel had made unlawful to himself before the Torah was revealed. Say, [O Muhammad], "So bring the Torah and recite it, if you should be truthful."' },
  { surahId: 3, ayahNumber: 94, text: 'And whoever invents about Allah untruth after that - then those are [truly] the wrongdoers.' },
  { surahId: 3, ayahNumber: 95, text: 'Say, "Allah has told the truth. So follow the religion of Abraham, inclining toward truth; and he was not of the polytheists."' },
  { surahId: 3, ayahNumber: 96, text: 'Indeed, the first House [of worship] established for mankind was that at Makkah - blessed and a guidance for the worlds.' },
  { surahId: 3, ayahNumber: 97, text: 'In it are clear signs [such as] the standing place of Abraham. And whoever enters it shall be safe. And [due] to Allah from the people is a pilgrimage to the House - for whoever is able to find thereto a way. But whoever disbelieves - then indeed, Allah is free from need of the worlds.' },
  { surahId: 3, ayahNumber: 98, text: 'Say, "O People of the Scripture, why do you disbelieve in the verses of Allah while Allah is Witness over what you do?"' },
  { surahId: 3, ayahNumber: 99, text: 'Say, "O People of the Scripture, why do you avert from the way of Allah those who believe, seeking to make it [seem] deviant, while you are witnesses [to the truth]? And Allah is not unaware of what you do."' },
  { surahId: 3, ayahNumber: 100, text: 'O you who have believed, if you obey a party of those who were given the Scripture, they would turn you back, after your belief, [to being] unbelievers.' },
  { surahId: 3, ayahNumber: 101, text: 'And how could you disbelieve while to you are being recited the verses of Allah and among you is His Messenger? And whoever holds firmly to Allah has [indeed] been guided to a straight path.' },
  { surahId: 3, ayahNumber: 102, text: 'O you who have believed, fear Allah as He should be feared and do not die except as Muslims [in submission to Him].' },
  { surahId: 3, ayahNumber: 103, text: 'And hold firmly to the rope of Allah all together and do not become divided. And remember the favor of Allah upon you - when you were enemies and He brought your hearts together and you became, by His favor, brothers. And you were on the edge of a pit of the Fire, and He saved you from it. Thus does Allah make clear to you His verses that you may be guided.' },
  { surahId: 3, ayahNumber: 104, text: 'And let there be [arising] from you a nation inviting to [all that is] good, enjoining what is right and forbidding what is wrong, and those will be the successful.' },
  { surahId: 3, ayahNumber: 105, text: 'And do not be like the ones who became divided and differed after the clear proofs had come to them. And those will have a great punishment.' },
  { surahId: 3, ayahNumber: 106, text: 'On the Day [some] faces will turn white and [some] faces will turn black. As for those whose faces turn black, [to them it will be said], "Did you disbelieve after your belief? Then taste the punishment for what you used to reject."' },
  { surahId: 3, ayahNumber: 107, text: 'But as for those whose faces will turn white, [they will be] within the mercy of Allah. They will abide therein eternally.' },
  { surahId: 3, ayahNumber: 108, text: 'These are the verses of Allah. We recite them to you, [O Muhammad], in truth; and Allah wants no injustice to the worlds.' },
  { surahId: 3, ayahNumber: 109, text: 'To Allah belongs whatever is in the heavens and whatever is on the earth. And to Allah will [all] matters be returned.' },
  { surahId: 3, ayahNumber: 110, text: 'You are the best nation produced [as an example] for mankind. You enjoin what is right and forbid what is wrong and believe in Allah. If only the People of the Scripture had believed, it would have been better for them. Among them are believers, but most of them are defiantly disobedient.' },
  { surahId: 3, ayahNumber: 111, text: 'They will not harm you except for [some] annoyance. And if they fight you, they will show you their backs; then they will not be aided.' },
  { surahId: 3, ayahNumber: 112, text: 'They have been put under humiliation [by Allah] wherever they are overtaken, except for a covenant from Allah and a rope from the Muslims. And they have drawn upon themselves anger from Allah and have been put under destitution. That is because they disbelieved in the verses of Allah and killed the prophets without right. That is because they disobeyed and [habitually] transgressed.' },
  { surahId: 3, ayahNumber: 113, text: 'They are not [all] the same; among the People of the Scripture is a community standing [in obedience], reciting the verses of Allah during periods of the night and prostrating [in prayer].' },
  { surahId: 3, ayahNumber: 114, text: 'They believe in Allah and the Last Day, and they enjoin what is right and forbid what is wrong and hasten to good deeds. And those are among the righteous.' },
  { surahId: 3, ayahNumber: 115, text: 'And whatever good they do - never will it be removed from them. And Allah is Knowing of the righteous.' },
  { surahId: 3, ayahNumber: 116, text: 'Indeed, those who disbelieve - never will their wealth or their children avail them against Allah at all, and those are the companions of the Fire; they will abide therein eternally.' },
  { surahId: 3, ayahNumber: 117, text: 'The example of what they spend in this worldly life is like that of a wind containing frost which strikes the harvest of a people who have wronged themselves and destroys it. And Allah has not wronged them, but they wrong themselves.' },
  { surahId: 3, ayahNumber: 118, text: 'O you who have believed, do not take as intimates those other than yourselves, for they will not spare you [any] ruin. They wish you would have hardship. Hatred has already appeared from their mouths, and what their breasts conceal is greater. We have certainly made clear to you the signs, if you will use reason.' },
  { surahId: 3, ayahNumber: 119, text: 'Here you are loving them but they are not loving you, while you believe in the Scripture - all of it. And when they meet you, they say, "We believe." But when they are alone, they bite their fingertips at you in rage. Say, "Die in your rage. Indeed, Allah is Knowing of that within the breasts."' },
  { surahId: 3, ayahNumber: 120, text: 'If good touches you, it distresses them; but if harm strikes you, they rejoice at it. And if you are patient and fear Allah, their plot will not harm you at all. Indeed, Allah is encompassing of what they do.' },
  { surahId: 3, ayahNumber: 121, text: 'And [remember] when you, [O Muhammad], left your family in the morning to post the believers at their stations for the battle [of Uhud] - and Allah is Hearing and Knowing -' },
  { surahId: 3, ayahNumber: 122, text: 'When two parties among you were about to lose courage, but Allah was their ally; and upon Allah the believers should rely.' },
  { surahId: 3, ayahNumber: 123, text: 'And already had Allah given you victory at [the battle of] Badr while you were few in number. Then fear Allah; perhaps you will be grateful.' },
  { surahId: 3, ayahNumber: 124, text: '[Remember] when you said to the believers, "Is it not sufficient for you that your Lord should reinforce you with three thousand angels sent down?' },
  { surahId: 3, ayahNumber: 125, text: 'Yes, if you remain patient and conscious of Allah and the enemy come upon you [attacking] in rage, your Lord will reinforce you with five thousand angels having marks [of distinction]' },
  { surahId: 3, ayahNumber: 126, text: 'And Allah made it not except as [a sign of] good tidings for you and to reassure your hearts thereby. And victory is not except from Allah, the Exalted in Might, the Wise -' },
  { surahId: 3, ayahNumber: 127, text: 'That He might cut down a section of the disbelievers or suppress them so that they turn back disappointed.' },
  { surahId: 3, ayahNumber: 128, text: 'Not for you, [O Muhammad, but for Allah], is the decision whether He should [cut them down] or forgive them or punish them, for indeed, they are wrongdoers.' },
  { surahId: 3, ayahNumber: 129, text: 'And to Allah belongs whatever is in the heavens and whatever is on the earth. He forgives whom He wills and punishes whom He wills. And Allah is Forgiving and Merciful.' },
  { surahId: 3, ayahNumber: 130, text: 'O you who have believed, do not consume usury, doubled and multiplied, but fear Allah that you may be successful.' },
  { surahId: 3, ayahNumber: 131, text: 'And fear the Fire, which has been prepared for the disbelievers.' },
  { surahId: 3, ayahNumber: 132, text: 'And obey Allah and the Messenger that you may obtain mercy.' },
  { surahId: 3, ayahNumber: 133, text: 'And hasten to forgiveness from your Lord and a garden as wide as the heavens and earth, prepared for the righteous' },
  { surahId: 3, ayahNumber: 134, text: 'Who spend [in the cause of Allah] during ease and hardship and who restrain anger and who pardon the people - and Allah loves the doers of good;' },
  { surahId: 3, ayahNumber: 135, text: 'And those who, when they commit an immorality or wrong themselves [by transgression], remember Allah and seek forgiveness for their sins - and who can forgive sins except Allah? - and [who] do not persist in what they have done while they know.' },
  { surahId: 3, ayahNumber: 136, text: 'Those - their reward is forgiveness from their Lord and gardens beneath which rivers flow [in Paradise], wherein they will abide eternally; and excellent is the reward of the [righteous] workers.' },
  { surahId: 3, ayahNumber: 137, text: 'Similar situations [as yours] have passed on before you, so proceed throughout the earth and observe how was the end of those who denied.' },
  { surahId: 3, ayahNumber: 138, text: 'This [Qur\'an] is a clear statement to [all] the people and a guidance and instruction for those conscious of Allah.' },
  { surahId: 3, ayahNumber: 139, text: 'So do not weaken and do not grieve, and you will be superior if you are [true] believers.' },
  { surahId: 3, ayahNumber: 140, text: 'If a wound should touch you - there has already touched the [opposing] people a wound similar to it. And these days [of varying conditions] We alternate among the people so that Allah may make evident those who believe and [may] take to Himself from among you martyrs - and Allah does not like the wrongdoers -' },
  { surahId: 3, ayahNumber: 141, text: 'And that Allah may purify the believers [through trials] and destroy the disbelievers.' },
  { surahId: 3, ayahNumber: 142, text: 'Or do you think that you will enter Paradise while Allah has not yet made evident those of you who fight in His cause and made evident those who are steadfast?' },
  { surahId: 3, ayahNumber: 143, text: 'And you had certainly wished for martyrdom before you encountered it, and you have [now] seen it [before you] while you were looking on.' },
  { surahId: 3, ayahNumber: 144, text: 'Muhammad is not but a messenger. [Other] messengers have passed on before him. So if he was to die or be killed, would you turn back on your heels [to unbelief]? And he who turns back on his heels will never harm Allah at all; but Allah will reward the grateful.' },
  { surahId: 3, ayahNumber: 145, text: 'And it is not [possible] for one to die except by permission of Allah at a decree determined. And whoever desires the reward of this world - We will give him thereof; and whoever desires the reward of the Hereafter - We will give him thereof. And we will reward the grateful.' },
  { surahId: 3, ayahNumber: 146, text: 'And how many a prophet [fought and] with him fought many religious scholars. But they never lost assurance due to what afflicted them in the cause of Allah, nor did they weaken or submit. And Allah loves the steadfast.' },
  { surahId: 3, ayahNumber: 147, text: 'And their words were not but that they said, "Our Lord, forgive us our sins and the excess [committed] in our affairs and plant firmly our feet and give us victory over the disbelieving people."' },
  { surahId: 3, ayahNumber: 148, text: 'So Allah gave them the reward of this world and the good reward of the Hereafter. And Allah loves the doers of good.' },
  { surahId: 3, ayahNumber: 149, text: 'O you who have believed, if you obey those who disbelieve, they will turn you back on your heels, and you will [then] become losers.' },
  { surahId: 3, ayahNumber: 150, text: 'But Allah is your protector, and He is the best of helpers.' },
  { surahId: 3, ayahNumber: 151, text: 'We will cast terror into the hearts of those who disbelieve for what they have associated with Allah of which He had not sent down [any] authority. And their refuge will be the Fire, and wretched is the residence of the wrongdoers.' },
  { surahId: 3, ayahNumber: 152, text: 'And Allah had certainly fulfilled His promise to you when you were killing the enemy by His permission until [the time] when you lost courage and fell to disputing about the order [given by the Prophet] and disobeyed after He had shown you that which you love. Among you are some who desire this world, and among you are some who desire the Hereafter. Then he turned you back from them [defeated] that He might test you. And He has already forgiven you, and Allah is the possessor of bounty for the believers.' },
  { surahId: 3, ayahNumber: 153, text: '[Remember] when you [fled and] climbed [the mountain] without looking aside at anyone while the Messenger was calling you from behind. So Allah repaid you with distress upon distress so you would not grieve for that which had escaped you [of victory and spoils of war] or [for] that which had befallen you [of injury and death]. And Allah is [fully] Acquainted with what you do.' },
  { surahId: 3, ayahNumber: 154, text: 'Then after distress, He sent down upon you security [in the form of] drowsiness, overcoming a faction of you, while another faction worried about themselves, thinking of Allah other than the truth - the thought of ignorance, saying, "Is there anything for us [to have done] in this matter?" Say, "Indeed, the matter belongs completely to Allah." They conceal within themselves what they will not reveal to you. They say, "If there was anything we could have done in the matter, some of us would not have been killed right here." Say, "Even if you had been inside your houses, those decreed to be killed would have come out to their death beds." [It was] so that Allah might test what is in your breasts and purify what is in your hearts. And Allah is Knowing of that within the breasts.' },
  { surahId: 3, ayahNumber: 155, text: 'Indeed, those of you who turned back on the day the two armies met, it was Satan who caused them to slip because of some [blame] they had earned. But Allah has already forgiven them. Indeed, Allah is Forgiving and Forbearing.' },
  { surahId: 3, ayahNumber: 156, text: 'O you who have believed, do not be like those who disbelieved and said about their brothers when they traveled through the land or went out to fight, "If they had been with us, they would not have died or have been killed," so Allah makes that [misconception] a regret within their hearts. And it is Allah who gives life and causes death, and Allah is Seeing of what you do.' },
  { surahId: 3, ayahNumber: 157, text: 'And if you are killed in the cause of Allah or die - then forgiveness from Allah and mercy are better than whatever they accumulate [in this world].' },
  { surahId: 3, ayahNumber: 158, text: 'And whether you die or are killed, unto Allah you will be gathered.' },
  { surahId: 3, ayahNumber: 159, text: 'So by mercy from Allah, [O Muhammad], you were lenient with them. And if you had been rude [in speech] and harsh in heart, they would have disbanded from about you. So pardon them and ask forgiveness for them and consult them in the matter. And when you have decided, then rely upon Allah. Indeed, Allah loves those who rely [upon Him].' },
  { surahId: 3, ayahNumber: 160, text: 'If Allah should aid you, no one can overcome you; but if He should forsake you, who is there that can aid you after Him? And upon Allah let the believers rely.' },
  { surahId: 3, ayahNumber: 161, text: 'It is not [attributable] to any prophet that he would act unfaithfully [in regard to war booty]. And whoever betrays, [taking unlawfully], will come with what he took on the Day of Resurrection. Then will every soul be [fully] compensated for what it earned, and they will not be wronged.' },
  { surahId: 3, ayahNumber: 162, text: 'So is one who pursues the pleasure of Allah like one who brings upon himself the anger of Allah and whose refuge is Hell? And wretched is the destination.' },
  { surahId: 3, ayahNumber: 163, text: 'They are [varying] degrees in the sight of Allah, and Allah is Seeing of whatever they do.' },
  { surahId: 3, ayahNumber: 164, text: 'Certainly did Allah confer [great] favor upon the believers when He sent among them a Messenger from themselves, reciting to them His verses and purifying them and teaching them the Book and wisdom, although they had been before in manifest error.' },
  { surahId: 3, ayahNumber: 165, text: 'Why [is it that] when a [single] disaster struck you [on the day of Uhud], although you had struck [the enemy in the battle of Badr] with one twice as great, you said, "From where is this?" Say, "It is from yourselves." Indeed, Allah is over all things competent.' },
  { surahId: 3, ayahNumber: 166, text: 'And what struck you on the day the two armies met was by permission of Allah that He might make evident the [true] believers.' },
  { surahId: 3, ayahNumber: 167, text: 'And that He might make evident those who are hypocrites. For it was said to them, "Come, fight in the way of Allah or [at least] defend." They said, "If we had known [there would be] fighting, we would have followed you." They were nearer to disbelief that day than to faith, saying with their mouths what was not in their hearts. And Allah is most Knowing of what they conceal -' },
  { surahId: 3, ayahNumber: 168, text: 'Those who said about their brothers while sitting [at home], "If they had obeyed us, they would not have been killed." Say, "Then prevent death from yourselves, if you should be truthful."' },
  { surahId: 3, ayahNumber: 169, text: 'And never think of those who have been killed in the cause of Allah as dead. Rather, they are alive with their Lord, receiving provision,' },
  { surahId: 3, ayahNumber: 170, text: 'Rejoicing in what Allah has bestowed upon them of His bounty, and they receive good tidings about those [to be martyred] after them who have not yet joined them - that there will be no fear concerning them, nor will they grieve.' },
  { surahId: 3, ayahNumber: 171, text: 'They receive good tidings of favor from Allah and bounty and [of the fact] that Allah does not allow the reward of believers to be lost -' },
  { surahId: 3, ayahNumber: 172, text: 'Those [believers] who responded to Allah and the Messenger after injury had struck them. For those who did good among them and feared Allah is a great reward -' },
  { surahId: 3, ayahNumber: 173, text: 'Those to whom hypocrites said, "Indeed, the people have gathered against you, so fear them." But it [merely] increased them in faith, and they said, "Sufficient for us is Allah, and [He is] the best Disposer of affairs."' },
  { surahId: 3, ayahNumber: 174, text: 'So they returned with favor from Allah and bounty, no harm having touched them. And they pursued the pleasure of Allah, and Allah is the possessor of great bounty.' },
  { surahId: 3, ayahNumber: 175, text: 'That is only Satan who frightens [you] of his supporters. So fear them not, but fear Me, if you are [indeed] believers.' },
  { surahId: 3, ayahNumber: 176, text: 'And do not be grieved, [O Muhammad], by those who hasten into disbelief. Indeed, they will never harm Allah at all. Allah intends that He should give them no share in the Hereafter, and for them is a great punishment.' },
  { surahId: 3, ayahNumber: 177, text: 'Indeed, those who purchase disbelief [in exchange] for faith - never will they harm Allah at all, and for them is a painful punishment.' },
  { surahId: 3, ayahNumber: 178, text: 'And let not those who disbelieve ever think that [because] We extend their time [of enjoyment] it is better for them. We only extend it for them so that they may increase in sin, and for them is a humiliating punishment.' },
  { surahId: 3, ayahNumber: 179, text: 'Allah would not leave the believers in that [state] you are in [presently] until He separates the evil from the good. Nor would Allah reveal to you the unseen. But [instead], Allah chooses of His messengers whom He wills, so believe in Allah and His messengers. And if you believe and fear Him, then for you is a great reward.' },
  { surahId: 3, ayahNumber: 180, text: 'And let not those who [greedily] withhold what Allah has given them of His bounty ever think that it is better for them. Rather, it is worse for them. Their necks will be encircled by what they withheld on the Day of Resurrection. And to Allah belongs the heritage of the heavens and the earth. And Allah, with what you do, is [fully] Acquainted.' },
  { surahId: 3, ayahNumber: 181, text: 'Allah has certainly heard the statement of those [Jews] who said, "Indeed, Allah is poor, while we are rich." We will record what they said and their killing of the prophets without right and will say, "Taste the punishment of the Burning Fire.' },
  { surahId: 3, ayahNumber: 182, text: 'That is for what your hands have put forth and because Allah is not ever unjust to [His] servants."' },
  { surahId: 3, ayahNumber: 183, text: '[They are] those who said, "Indeed, Allah has taken our promise not to believe any messenger until he brings us an offering which fire [from heaven] will consume." Say, "There have already come to you messengers before me with clear proofs and [even] that of which you speak. So why did you kill them, if you should be truthful?"' },
  { surahId: 3, ayahNumber: 184, text: 'Then if they deny you, [O Muhammad] - so were messengers denied before you, who brought clear proofs and written ordinances and the enlightening Scripture.' },
  { surahId: 3, ayahNumber: 185, text: 'Every soul will taste death, and you will only be given your [full] compensation on the Day of Resurrection. So he who is drawn away from the Fire and admitted to Paradise has attained [his desire]. And what is the life of this world except the enjoyment of delusion.' },
  { surahId: 3, ayahNumber: 186, text: 'You will surely be tested in your possessions and in yourselves. And you will surely hear from those who were given the Scripture before you and from those who associate others with Allah much abuse. But if you are patient and fear Allah - indeed, that is of the matters [worthy] of determination.' },
  { surahId: 3, ayahNumber: 187, text: 'And [mention, O Muhammad], when Allah took a covenant from those who were given the Scripture, [saying], "You must make it clear to the people and not conceal it." But they threw it away behind their backs and exchanged it for a small price. And wretched is that which they purchased.' },
  { surahId: 3, ayahNumber: 188, text: 'And never think that those who rejoice in what they have perpetrated and like to be praised for what they did not do - never think them [to be] in safety from the punishment, and for them is a painful punishment.' },
  { surahId: 3, ayahNumber: 189, text: 'And to Allah belongs the dominion of the heavens and the earth, and Allah is over all things competent.' },
  { surahId: 3, ayahNumber: 190, text: 'Indeed, in the creation of the heavens and the earth and the alternation of the night and the day are signs for those of understanding.' },
  { surahId: 3, ayahNumber: 191, text: 'Who remember Allah while standing or sitting or [lying] on their sides and give thought to the creation of the heavens and the earth, [saying], "Our Lord, You did not create this aimlessly; exalted are You [above such a thing]; then protect us from the punishment of the Fire.' },
  { surahId: 3, ayahNumber: 192, text: 'Our Lord, indeed whoever You admit to the Fire - You have disgraced him, and for the wrongdoers there are no helpers.' },
  { surahId: 3, ayahNumber: 193, text: 'Our Lord, indeed we have heard a caller calling to faith, [saying], \'Believe in your Lord,\' and we have believed. Our Lord, so forgive us our sins and remove from us our misdeeds and cause us to die with the righteous.' },
  { surahId: 3, ayahNumber: 194, text: 'Our Lord, and grant us what You promised us through Your messengers and do not disgrace us on the Day of Resurrection. Indeed, You do not fail in [Your] promise."' },
  { surahId: 3, ayahNumber: 195, text: 'And their Lord responded to them, "Never will I allow to be lost the work of [any] worker among you, whether male or female; you are of one another. So those who emigrated or were evicted from their homes or were harmed in My cause or fought or were killed - I will surely remove from them their misdeeds, and I will surely admit them to gardens beneath which rivers flow as reward from Allah, and Allah has with Him the best reward."' },
  { surahId: 3, ayahNumber: 196, text: 'Be not deceived by the [uninhibited] movement of the disbelievers throughout the land.' },
  { surahId: 3, ayahNumber: 197, text: '[It is but] a small enjoyment; then their [final] refuge is Hell, and wretched is the resting place.' },
  { surahId: 3, ayahNumber: 198, text: 'But those who feared their Lord will have gardens beneath which rivers flow, abiding eternally therein, as accommodation from Allah. And that which is with Allah is best for the righteous.' },
  { surahId: 3, ayahNumber: 199, text: 'And indeed, among the People of the Scripture are those who believe in Allah and what was revealed to you and what was revealed to them, [being] humbly submissive to Allah. They do not exchange the verses of Allah for a small price. Those will have their reward with their Lord. Indeed, Allah is swift in account.' },
  { surahId: 3, ayahNumber: 200, text: 'O you who have believed, persevere and endure and remain stationed and fear Allah that you may be successful.' },
  { surahId: 4, ayahNumber: 1, text: 'O mankind, fear your Lord, who created you from one soul and created from it its mate and dispersed from both of them many men and women. And fear Allah, through whom you ask one another, and the wombs. Indeed Allah is ever, over you, an Observer.' },
  { surahId: 4, ayahNumber: 2, text: 'And give to the orphans their properties and do not substitute the defective [of your own] for the good [of theirs]. And do not consume their properties into your own. Indeed, that is ever a great sin.' },
  { surahId: 4, ayahNumber: 3, text: 'And if you fear that you will not deal justly with the orphan girls, then marry those that please you of [other] women, two or three or four. But if you fear that you will not be just, then [marry only] one or those your right hand possesses. That is more suitable that you may not incline [to injustice].' },
  { surahId: 4, ayahNumber: 4, text: 'And give the women [upon marriage] their [bridal] gifts graciously. But if they give up willingly to you anything of it, then take it in satisfaction and ease.' },
  { surahId: 4, ayahNumber: 5, text: 'And do not give the weak-minded your property, which Allah has made a means of sustenance for you, but provide for them with it and clothe them and speak to them words of appropriate kindness.' },
  { surahId: 4, ayahNumber: 6, text: 'And test the orphans [in their abilities] until they reach marriageable age. Then if you perceive in them sound judgement, release their property to them. And do not consume it excessively and quickly, [anticipating] that they will grow up. And whoever, [when acting as guardian], is self-sufficient should refrain [from taking a fee]; and whoever is poor - let him take according to what is acceptable. Then when you release their property to them, bring witnesses upon them. And sufficient is Allah as Accountant.' },
  { surahId: 4, ayahNumber: 7, text: 'For men is a share of what the parents and close relatives leave, and for women is a share of what the parents and close relatives leave, be it little or much - an obligatory share.' },
  { surahId: 4, ayahNumber: 8, text: 'And when [other] relatives and orphans and the needy are present at the [time of] division, then provide for them [something] out of the estate and speak to them words of appropriate kindness.' },
  { surahId: 4, ayahNumber: 9, text: 'And let those [executors and guardians] fear [injustice] as if they [themselves] had left weak offspring behind and feared for them. So let them fear Allah and speak words of appropriate justice.' },
  { surahId: 4, ayahNumber: 10, text: 'Indeed, those who devour the property of orphans unjustly are only consuming into their bellies fire. And they will be burned in a Blaze.' },
  { surahId: 4, ayahNumber: 11, text: 'Allah instructs you concerning your children: for the male, what is equal to the share of two females. But if there are [only] daughters, two or more, for them is two thirds of one\'s estate. And if there is only one, for her is half. And for one\'s parents, to each one of them is a sixth of his estate if he left children. But if he had no children and the parents [alone] inherit from him, then for his mother is one third. And if he had brothers [or sisters], for his mother is a sixth, after any bequest he [may have] made or debt. Your parents or your children - you know not which of them are nearest to you in benefit. [These shares are] an obligation [imposed] by Allah. Indeed, Allah is ever Knowing and Wise.' },
  { surahId: 4, ayahNumber: 12, text: 'And for you is half of what your wives leave if they have no child. But if they have a child, for you is one fourth of what they leave, after any bequest they [may have] made or debt. And for the wives is one fourth if you leave no child. But if you leave a child, then for them is an eighth of what you leave, after any bequest you [may have] made or debt. And if a man or woman leaves neither ascendants nor descendants but has a brother or a sister, then for each one of them is a sixth. But if they are more than two, they share a third, after any bequest which was made or debt, as long as there is no detriment [caused]. [This is] an ordinance from Allah, and Allah is Knowing and Forbearing.' },
  { surahId: 4, ayahNumber: 13, text: 'These are the limits [set by] Allah, and whoever obeys Allah and His Messenger will be admitted by Him to gardens [in Paradise] under which rivers flow, abiding eternally therein; and that is the great attainment.' },
  { surahId: 4, ayahNumber: 14, text: 'And whoever disobeys Allah and His Messenger and transgresses His limits - He will put him into the Fire to abide eternally therein, and he will have a humiliating punishment.' },
  { surahId: 4, ayahNumber: 15, text: 'Those who commit unlawful sexual intercourse of your women - bring against them four [witnesses] from among you. And if they testify, confine the guilty women to houses until death takes them or Allah ordains for them [another] way.' },
  { surahId: 4, ayahNumber: 16, text: 'And the two who commit it among you, dishonor them both. But if they repent and correct themselves, leave them alone. Indeed, Allah is ever Accepting of repentance and Merciful.' },
  { surahId: 4, ayahNumber: 17, text: 'The repentance accepted by Allah is only for those who do wrong in ignorance [or carelessness] and then repent soon after. It is those to whom Allah will turn in forgiveness, and Allah is ever Knowing and Wise.' },
  { surahId: 4, ayahNumber: 18, text: 'But repentance is not [accepted] of those who [continue to] do evil deeds up until, when death comes to one of them, he says, "Indeed, I have repented now," or of those who die while they are disbelievers. For them We have prepared a painful punishment.' },
  { surahId: 4, ayahNumber: 19, text: 'O you who have believed, it is not lawful for you to inherit women by compulsion. And do not make difficulties for them in order to take [back] part of what you gave them unless they commit a clear immorality. And live with them in kindness. For if you dislike them - perhaps you dislike a thing and Allah makes therein much good.' },
  { surahId: 4, ayahNumber: 20, text: 'But if you want to replace one wife with another and you have given one of them a great amount [in gifts], do not take [back] from it anything. Would you take it in injustice and manifest sin?' },
  { surahId: 4, ayahNumber: 21, text: 'And how could you take it while you have gone in unto each other and they have taken from you a solemn covenant?' },
  { surahId: 4, ayahNumber: 22, text: 'And do not marry those [women] whom your fathers married, except what has already occurred. Indeed, it was an immorality and hateful [to Allah] and was evil as a way.' },
  { surahId: 4, ayahNumber: 23, text: 'Prohibited to you [for marriage] are your mothers, your daughters, your sisters, your father\'s sisters, your mother\'s sisters, your brother\'s daughters, your sister\'s daughters, your [milk] mothers who nursed you, your sisters through nursing, your wives\' mothers, and your step-daughters under your guardianship [born] of your wives unto whom you have gone in. But if you have not gone in unto them, there is no sin upon you. And [also prohibited are] the wives of your sons who are from your [own] loins, and that you take [in marriage] two sisters simultaneously, except for what has already occurred. Indeed, Allah is ever Forgiving and Merciful.' },
  { surahId: 4, ayahNumber: 24, text: 'And [also prohibited to you are all] married women except those your right hands possess. [This is] the decree of Allah upon you. And lawful to you are [all others] beyond these, [provided] that you seek them [in marriage] with [gifts from] your property, desiring chastity, not unlawful sexual intercourse. So for whatever you enjoy [of marriage] from them, give them their due compensation as an obligation. And there is no blame upon you for what you mutually agree to beyond the obligation. Indeed, Allah is ever Knowing and Wise.' },
  { surahId: 4, ayahNumber: 25, text: 'And whoever among you cannot [find] the means to marry free, believing women, then [he may marry] from those whom your right hands possess of believing slave girls. And Allah is most knowing about your faith. You [believers] are of one another. So marry them with the permission of their people and give them their due compensation according to what is acceptable. [They should be] chaste, neither [of] those who commit unlawful intercourse randomly nor those who take [secret] lovers. But once they are sheltered in marriage, if they should commit adultery, then for them is half the punishment for free [unmarried] women. This [allowance] is for him among you who fears sin, but to be patient is better for you. And Allah is Forgiving and Merciful.' },
  { surahId: 4, ayahNumber: 26, text: 'Allah wants to make clear to you [the lawful from the unlawful] and guide you to the [good] practices of those before you and to accept your repentance. And Allah is Knowing and Wise.' },
  { surahId: 4, ayahNumber: 27, text: 'Allah wants to accept your repentance, but those who follow [their] passions want you to digress [into] a great deviation.' },
  { surahId: 4, ayahNumber: 28, text: 'And Allah wants to lighten for you [your difficulties]; and mankind was created weak.' },
  { surahId: 4, ayahNumber: 29, text: 'O you who have believed, do not consume one another\'s wealth unjustly but only [in lawful] business by mutual consent. And do not kill yourselves [or one another]. Indeed, Allah is to you ever Merciful.' },
  { surahId: 4, ayahNumber: 30, text: 'And whoever does that in aggression and injustice - then We will drive him into a Fire. And that, for Allah, is [always] easy.' },
  { surahId: 4, ayahNumber: 31, text: 'If you avoid the major sins which you are forbidden, We will remove from you your lesser sins and admit you to a noble entrance [into Paradise].' },
  { surahId: 4, ayahNumber: 32, text: 'And do not wish for that by which Allah has made some of you exceed others. For men is a share of what they have earned, and for women is a share of what they have earned. And ask Allah of his bounty. Indeed Allah is ever, of all things, Knowing.' },
  { surahId: 4, ayahNumber: 33, text: 'And for all, We have made heirs to what is left by parents and relatives. And to those whom your oaths have bound [to you] - give them their share. Indeed Allah is ever, over all things, a Witness.' },
  { surahId: 4, ayahNumber: 34, text: 'Men are in charge of women by [right of] what Allah has given one over the other and what they spend [for maintenance] from their wealth. So righteous women are devoutly obedient, guarding in [the husband\'s] absence what Allah would have them guard. But those [wives] from whom you fear arrogance - [first] advise them; [then if they persist], forsake them in bed; and [finally], strike them. But if they obey you [once more], seek no means against them. Indeed, Allah is ever Exalted and Grand.' },
  { surahId: 4, ayahNumber: 35, text: 'And if you fear dissension between the two, send an arbitrator from his people and an arbitrator from her people. If they both desire reconciliation, Allah will cause it between them. Indeed, Allah is ever Knowing and Acquainted [with all things].' },
  { surahId: 4, ayahNumber: 36, text: 'Worship Allah and associate nothing with Him, and to parents do good, and to relatives, orphans, the needy, the near neighbor, the neighbor farther away, the companion at your side, the traveler, and those whom your right hands possess. Indeed, Allah does not like those who are self-deluding and boastful.' },
  { surahId: 4, ayahNumber: 37, text: 'Who are stingy and enjoin upon [other] people stinginess and conceal what Allah has given them of His bounty - and We have prepared for the disbelievers a humiliating punishment -' },
  { surahId: 4, ayahNumber: 38, text: 'And [also] those who spend of their wealth to be seen by the people and believe not in Allah nor in the Last Day. And he to whom Satan is a companion - then evil is he as a companion.' },
  { surahId: 4, ayahNumber: 39, text: 'And what [harm would come] upon them if they believed in Allah and the Last Day and spent out of what Allah provided for them? And Allah is ever, about them, Knowing.' },
  { surahId: 4, ayahNumber: 40, text: 'Indeed, Allah does not do injustice, [even] as much as an atom\'s weight; while if there is a good deed, He multiplies it and gives from Himself a great reward.' },
  { surahId: 4, ayahNumber: 41, text: 'So how [will it be] when We bring from every nation a witness and we bring you, [O Muhammad] against these [people] as a witness?' },
  { surahId: 4, ayahNumber: 42, text: 'That Day, those who disbelieved and disobeyed the Messenger will wish they could be covered by the earth. And they will not conceal from Allah a [single] statement.' },
  { surahId: 4, ayahNumber: 43, text: 'O you who have believed, do not approach prayer while you are intoxicated until you know what you are saying or in a state of janabah, except those passing through [a place of prayer], until you have washed [your whole body]. And if you are ill or on a journey or one of you comes from the place of relieving himself or you have contacted women and find no water, then seek clean earth and wipe over your faces and your hands [with it]. Indeed, Allah is ever Pardoning and Forgiving.' },
  { surahId: 4, ayahNumber: 44, text: 'Have you not seen those who were given a portion of the Scripture, purchasing error [in exchange for it] and wishing you would lose the way?' },
  { surahId: 4, ayahNumber: 45, text: 'And Allah is most knowing of your enemies; and sufficient is Allah as an ally, and sufficient is Allah as a helper.' },
  { surahId: 4, ayahNumber: 46, text: 'Among the Jews are those who distort words from their [proper] usages and say, "We hear and disobey" and "Hear but be not heard" and "Ra\'ina," twisting their tongues and defaming the religion. And if they had said [instead], "We hear and obey" and "Wait for us [to understand]," it would have been better for them and more suitable. But Allah has cursed them for their disbelief, so they believe not, except for a few.' },
  { surahId: 4, ayahNumber: 47, text: 'O you who were given the Scripture, believe in what We have sent down [to Muhammad], confirming that which is with you, before We obliterate faces and turn them toward their backs or curse them as We cursed the sabbath-breakers. And ever is the decree of Allah accomplished.' },
  { surahId: 4, ayahNumber: 48, text: 'Indeed, Allah does not forgive association with Him, but He forgives what is less than that for whom He wills. And he who associates others with Allah has certainly fabricated a tremendous sin.' },
  { surahId: 4, ayahNumber: 49, text: 'Have you not seen those who claim themselves to be pure? Rather, Allah purifies whom He wills, and injustice is not done to them, [even] as much as a thread [inside a date seed].' },
  { surahId: 4, ayahNumber: 50, text: 'Look how they invent about Allah untruth, and sufficient is that as a manifest sin.' },
  { surahId: 4, ayahNumber: 51, text: 'Have you not seen those who were given a portion of the Scripture, who believe in superstition and false objects of worship and say about the disbelievers, "These are better guided than the believers as to the way"?' },
  { surahId: 4, ayahNumber: 52, text: 'Those are the ones whom Allah has cursed; and he whom Allah curses - never will you find for him a helper.' },
  { surahId: 4, ayahNumber: 53, text: 'Or have they a share of dominion? Then [if that were so], they would not give the people [even as much as] the speck on a date seed.' },
  { surahId: 4, ayahNumber: 54, text: 'Or do they envy people for what Allah has given them of His bounty? But we had already given the family of Abraham the Scripture and wisdom and conferred upon them a great kingdom.' },
  { surahId: 4, ayahNumber: 55, text: 'And some among them believed in it, and some among them were averse to it. And sufficient is Hell as a blaze.' },
  { surahId: 4, ayahNumber: 56, text: 'Indeed, those who disbelieve in Our verses - We will drive them into a Fire. Every time their skins are roasted through We will replace them with other skins so they may taste the punishment. Indeed, Allah is ever Exalted in Might and Wise.' },
  { surahId: 4, ayahNumber: 57, text: 'But those who believe and do righteous deeds - We will admit them to gardens beneath which rivers flow, wherein they abide forever. For them therein are purified spouses, and We will admit them to deepening shade.' },
  { surahId: 4, ayahNumber: 58, text: 'Indeed, Allah commands you to render trusts to whom they are due and when you judge between people to judge with justice. Excellent is that which Allah instructs you. Indeed, Allah is ever Hearing and Seeing.' },
  { surahId: 4, ayahNumber: 59, text: 'O you who have believed, obey Allah and obey the Messenger and those in authority among you. And if you disagree over anything, refer it to Allah and the Messenger, if you should believe in Allah and the Last Day. That is the best [way] and best in result.' },
  { surahId: 4, ayahNumber: 60, text: 'Have you not seen those who claim to have believed in what was revealed to you, [O Muhammad], and what was revealed before you? They wish to refer legislation to Taghut, while they were commanded to reject it; and Satan wishes to lead them far astray.' },
  { surahId: 4, ayahNumber: 61, text: 'And when it is said to them, "Come to what Allah has revealed and to the Messenger," you see the hypocrites turning away from you in aversion.' },
  { surahId: 4, ayahNumber: 62, text: 'So how [will it be] when disaster strikes them because of what their hands have put forth and then they come to you swearing by Allah, "We intended nothing but good conduct and accommodation."' },
  { surahId: 4, ayahNumber: 63, text: 'Those are the ones of whom Allah knows what is in their hearts, so turn away from them but admonish them and speak to them a far-reaching word.' },
  { surahId: 4, ayahNumber: 64, text: 'And We did not send any messenger except to be obeyed by permission of Allah. And if, when they wronged themselves, they had come to you, [O Muhammad], and asked forgiveness of Allah and the Messenger had asked forgiveness for them, they would have found Allah Accepting of repentance and Merciful.' },
  { surahId: 4, ayahNumber: 65, text: 'But no, by your Lord, they will not [truly] believe until they make you, [O Muhammad], judge concerning that over which they dispute among themselves and then find within themselves no discomfort from what you have judged and submit in [full, willing] submission.' },
  { surahId: 4, ayahNumber: 66, text: 'And if We had decreed upon them, "Kill yourselves" or "Leave your homes," they would not have done it, except for a few of them. But if they had done what they were instructed, it would have been better for them and a firmer position [for them in faith].' },
  { surahId: 4, ayahNumber: 67, text: 'And then We would have given them from Us a great reward.' },
  { surahId: 4, ayahNumber: 68, text: 'And We would have guided them to a straight path.' },
  { surahId: 4, ayahNumber: 69, text: 'And whoever obeys Allah and the Messenger - those will be with the ones upon whom Allah has bestowed favor of the prophets, the steadfast affirmers of truth, the martyrs and the righteous. And excellent are those as companions.' },
  { surahId: 4, ayahNumber: 70, text: 'That is the bounty from Allah, and sufficient is Allah as Knower.' },
  { surahId: 4, ayahNumber: 71, text: 'O you who have believed, take your precaution and [either] go forth in companies or go forth all together.' },
  { surahId: 4, ayahNumber: 72, text: 'And indeed, there is among you he who lingers behind; and if disaster strikes you, he says, "Allah has favored me in that I was not present with them."' },
  { surahId: 4, ayahNumber: 73, text: 'But if bounty comes to you from Allah, he will surely say, as if there had never been between you and him any affection. "Oh, I wish I had been with them so I could have attained a great attainment."' },
  { surahId: 4, ayahNumber: 74, text: 'So let those fight in the cause of Allah who sell the life of this world for the Hereafter. And he who fights in the cause of Allah and is killed or achieves victory - We will bestow upon him a great reward.' },
  { surahId: 4, ayahNumber: 75, text: 'And what is [the matter] with you that you fight not in the cause of Allah and [for] the oppressed among men, women, and children who say, "Our Lord, take us out of this city of oppressive people and appoint for us from Yourself a protector and appoint for us from Yourself a helper?"' },
  { surahId: 4, ayahNumber: 76, text: 'Those who believe fight in the cause of Allah, and those who disbelieve fight in the cause of Taghut. So fight against the allies of Satan. Indeed, the plot of Satan has ever been weak.' },
  { surahId: 4, ayahNumber: 77, text: 'Have you not seen those who were told, "Restrain your hands [from fighting] and establish prayer and give zakah"? But then when fighting was ordained for them, at once a party of them feared men as they fear Allah or with [even] greater fear. They said, "Our Lord, why have You decreed upon us fighting? If only You had postponed [it for] us for a short time." Say, The enjoyment of this world is little, and the Hereafter is better for he who fears Allah. And injustice will not be done to you, [even] as much as a thread [inside a date seed]."' },
  { surahId: 4, ayahNumber: 78, text: 'Wherever you may be, death will overtake you, even if you should be within towers of lofty construction. But if good comes to them, they say, "This is from Allah "; and if evil befalls them, they say, "This is from you." Say, "All [things] are from Allah." So what is [the matter] with those people that they can hardly understand any statement?' },
  { surahId: 4, ayahNumber: 79, text: 'What comes to you of good is from Allah, but what comes to you of evil, [O man], is from yourself. And We have sent you, [O Muhammad], to the people as a messenger, and sufficient is Allah as Witness.' },
  { surahId: 4, ayahNumber: 80, text: 'He who obeys the Messenger has obeyed Allah; but those who turn away - We have not sent you over them as a guardian.' },
  { surahId: 4, ayahNumber: 81, text: 'And they say, "[We pledge] obedience." But when they leave you, a group of them spend the night determining to do other than what you say. But Allah records what they plan by night. So leave them alone and rely upon Allah. And sufficient is Allah as Disposer of affairs.' },
  { surahId: 4, ayahNumber: 82, text: 'Then do they not reflect upon the Qur\'an? If it had been from [any] other than Allah, they would have found within it much contradiction.' },
  { surahId: 4, ayahNumber: 83, text: 'And when there comes to them information about [public] security or fear, they spread it around. But if they had referred it back to the Messenger or to those of authority among them, then the ones who [can] draw correct conclusions from it would have known about it. And if not for the favor of Allah upon you and His mercy, you would have followed Satan, except for a few.' },
  { surahId: 4, ayahNumber: 84, text: 'So fight, [O Muhammad], in the cause of Allah; you are not held responsible except for yourself. And encourage the believers [to join you] that perhaps Allah will restrain the [military] might of those who disbelieve. And Allah is greater in might and stronger in [exemplary] punishment.' },
  { surahId: 4, ayahNumber: 85, text: 'Whoever intercedes for a good cause will have a reward therefrom; and whoever intercedes for an evil cause will have a burden therefrom. And ever is Allah, over all things, a Keeper.' },
  { surahId: 4, ayahNumber: 86, text: 'And when you are greeted with a greeting, greet [in return] with one better than it or [at least] return it [in a like manner]. Indeed, Allah is ever, over all things, an Accountant.' },
  { surahId: 4, ayahNumber: 87, text: 'Allah - there is no deity except Him. He will surely assemble you for [account on] the Day of Resurrection, about which there is no doubt. And who is more truthful than Allah in statement.' },
  { surahId: 4, ayahNumber: 88, text: 'What is [the matter] with you [that you are] two groups concerning the hypocrites, while Allah has made them fall back [into error and disbelief] for what they earned. Do you wish to guide those whom Allah has sent astray? And he whom Allah sends astray - never will you find for him a way [of guidance].' },
  { surahId: 4, ayahNumber: 89, text: 'They wish you would disbelieve as they disbelieved so you would be alike. So do not take from among them allies until they emigrate for the cause of Allah. But if they turn away, then seize them and kill them wherever you find them and take not from among them any ally or helper.' },
  { surahId: 4, ayahNumber: 90, text: 'Except for those who take refuge with a people between yourselves and whom is a treaty or those who come to you, their hearts strained at [the prospect of] fighting you or fighting their own people. And if Allah had willed, He could have given them power over you, and they would have fought you. So if they remove themselves from you and do not fight you and offer you peace, then Allah has not made for you a cause [for fighting] against them.' },
  { surahId: 4, ayahNumber: 91, text: 'You will find others who wish to obtain security from you and [to] obtain security from their people. Every time they are returned to [the influence of] disbelief, they fall back into it. So if they do not withdraw from you or offer you peace or restrain their hands, then seize them and kill them wherever you overtake them. And those - We have made for you against them a clear authorization.' },
  { surahId: 4, ayahNumber: 92, text: 'And never is it for a believer to kill a believer except by mistake. And whoever kills a believer by mistake - then the freeing of a believing slave and a compensation payment presented to the deceased\'s family [is required] unless they give [up their right as] charity. But if the deceased was from a people at war with you and he was a believer - then [only] the freeing of a believing slave; and if he was from a people with whom you have a treaty - then a compensation payment presented to his family and the freeing of a believing slave. And whoever does not find [one or cannot afford to buy one] - then [instead], a fast for two months consecutively, [seeking] acceptance of repentance from Allah. And Allah is ever Knowing and Wise.' },
  { surahId: 4, ayahNumber: 93, text: 'But whoever kills a believer intentionally - his recompense is Hell, wherein he will abide eternally, and Allah has become angry with him and has cursed him and has prepared for him a great punishment.' },
  { surahId: 4, ayahNumber: 94, text: 'O you who have believed, when you go forth [to fight] in the cause of Allah, investigate; and do not say to one who gives you [a greeting of] peace "You are not a believer," aspiring for the goods of worldly life; for with Allah are many acquisitions. You [yourselves] were like that before; then Allah conferred His favor upon you, so investigate. Indeed Allah is ever, with what you do, Acquainted.' },
  { surahId: 4, ayahNumber: 95, text: 'Not equal are those believers remaining [at home] - other than the disabled - and the mujahideen, [who strive and fight] in the cause of Allah with their wealth and their lives. Allah has preferred the mujahideen through their wealth and their lives over those who remain [behind], by degrees. And to both Allah has promised the best [reward]. But Allah has preferred the mujahideen over those who remain [behind] with a great reward -' },
  { surahId: 4, ayahNumber: 96, text: 'Degrees [of high position] from Him and forgiveness and mercy. And Allah is ever Forgiving and Merciful.' },
  { surahId: 4, ayahNumber: 97, text: 'Indeed, those whom the angels take [in death] while wronging themselves - [the angels] will say, "In what [condition] were you?" They will say, "We were oppressed in the land." The angels will say, "Was not the earth of Allah spacious [enough] for you to emigrate therein?" For those, their refuge is Hell - and evil it is as a destination.' },
  { surahId: 4, ayahNumber: 98, text: 'Except for the oppressed among men, women and children who cannot devise a plan nor are they directed to a way -' },
  { surahId: 4, ayahNumber: 99, text: 'For those it is expected that Allah will pardon them, and Allah is ever Pardoning and Forgiving.' },
  { surahId: 4, ayahNumber: 100, text: 'And whoever emigrates for the cause of Allah will find on the earth many [alternative] locations and abundance. And whoever leaves his home as an emigrant to Allah and His Messenger and then death overtakes him - his reward has already become incumbent upon Allah. And Allah is ever Forgiving and Merciful.' },
  { surahId: 4, ayahNumber: 101, text: 'And when you travel throughout the land, there is no blame upon you for shortening the prayer, [especially] if you fear that those who disbelieve may disrupt [or attack] you. Indeed, the disbelievers are ever to you a clear enemy.' },
  { surahId: 4, ayahNumber: 102, text: 'And when you are among them and lead them in prayer, let a group of them stand [in prayer] with you and let them carry their arms. And when they have prostrated, let them be [in position] behind you and have the other group come forward which has not [yet] prayed and let them pray with you, taking precaution and carrying their arms. Those who disbelieve wish that you would neglect your weapons and your baggage so they could come down upon you in one [single] attack. But there is no blame upon you, if you are troubled by rain or are ill, for putting down your arms, but take precaution. Indeed, Allah has prepared for the disbelievers a humiliating punishment.' },
  { surahId: 4, ayahNumber: 103, text: 'And when you have completed the prayer, remember Allah standing, sitting, or [lying] on your sides. But when you become secure, re-establish [regular] prayer. Indeed, prayer has been decreed upon the believers a decree of specified times.' },
  { surahId: 4, ayahNumber: 104, text: 'And do not weaken in pursuit of the enemy. If you should be suffering - so are they suffering as you are suffering, but you expect from Allah that which they expect not. And Allah is ever Knowing and Wise.' },
  { surahId: 4, ayahNumber: 105, text: 'Indeed, We have revealed to you, [O Muhammad], the Book in truth so you may judge between the people by that which Allah has shown you. And do not be for the deceitful an advocate.' },
  { surahId: 4, ayahNumber: 106, text: 'And seek forgiveness of Allah. Indeed, Allah is ever Forgiving and Merciful.' },
  { surahId: 4, ayahNumber: 107, text: 'And do not argue on behalf of those who deceive themselves. Indeed, Allah loves not one who is a habitually sinful deceiver.' },
  { surahId: 4, ayahNumber: 108, text: 'They conceal [their evil intentions and deeds] from the people, but they cannot conceal [them] from Allah, and He is with them [in His knowledge] when they spend the night in such as He does not accept of speech. And ever is Allah, of what they do, encompassing.' },
  { surahId: 4, ayahNumber: 109, text: 'Here you are - those who argue on their behalf in [this] worldly life - but who will argue with Allah for them on the Day of Resurrection, or who will [then] be their representative?' },
  { surahId: 4, ayahNumber: 110, text: 'And whoever does a wrong or wrongs himself but then seeks forgiveness of Allah will find Allah Forgiving and Merciful.' },
  { surahId: 4, ayahNumber: 111, text: 'And whoever commits a sin only earns it against himself. And Allah is ever Knowing and Wise.' },
  { surahId: 4, ayahNumber: 112, text: 'But whoever earns an offense or a sin and then blames it on an innocent [person] has taken upon himself a slander and manifest sin.' },
  { surahId: 4, ayahNumber: 113, text: 'And if it was not for the favor of Allah upon you, [O Muhammad], and His mercy, a group of them would have determined to mislead you. But they do not mislead except themselves, and they will not harm you at all. And Allah has revealed to you the Book and wisdom and has taught you that which you did not know. And ever has the favor of Allah upon you been great.' },
  { surahId: 4, ayahNumber: 114, text: 'No good is there in much of their private conversation, except for those who enjoin charity or that which is right or conciliation between people. And whoever does that seeking means to the approval of Allah - then We are going to give him a great reward.' },
  { surahId: 4, ayahNumber: 115, text: 'And whoever opposes the Messenger after guidance has become clear to him and follows other than the way of the believers - We will give him what he has taken and drive him into Hell, and evil it is as a destination.' },
  { surahId: 4, ayahNumber: 116, text: 'Indeed, Allah does not forgive association with Him, but He forgives what is less than that for whom He wills. And he who associates others with Allah has certainly gone far astray.' },
  { surahId: 4, ayahNumber: 117, text: 'They call upon instead of Him none but female [deities], and they [actually] call upon none but a rebellious Satan.' },
  { surahId: 4, ayahNumber: 118, text: 'Whom Allah has cursed. For he had said, "I will surely take from among Your servants a specific portion.' },
  { surahId: 4, ayahNumber: 119, text: 'And I will mislead them, and I will arouse in them [sinful] desires, and I will command them so they will slit the ears of cattle, and I will command them so they will change the creation of Allah." And whoever takes Satan as an ally instead of Allah has certainly sustained a clear loss.' },
  { surahId: 4, ayahNumber: 120, text: 'Satan promises them and arouses desire in them. But Satan does not promise them except delusion.' },
  { surahId: 4, ayahNumber: 121, text: 'The refuge of those will be Hell, and they will not find from it an escape.' },
  { surahId: 4, ayahNumber: 122, text: 'But the ones who believe and do righteous deeds - We will admit them to gardens beneath which rivers flow, wherein they will abide forever. [It is] the promise of Allah, [which is] truth, and who is more truthful than Allah in statement.' },
  { surahId: 4, ayahNumber: 123, text: 'Paradise is not [obtained] by your wishful thinking nor by that of the People of the Scripture. Whoever does a wrong will be recompensed for it, and he will not find besides Allah a protector or a helper.' },
  { surahId: 4, ayahNumber: 124, text: 'And whoever does righteous deeds, whether male or female, while being a believer - those will enter Paradise and will not be wronged, [even as much as] the speck on a date seed.' },
  { surahId: 4, ayahNumber: 125, text: 'And who is better in religion than one who submits himself to Allah while being a doer of good and follows the religion of Abraham, inclining toward truth? And Allah took Abraham as an intimate friend.' },
  { surahId: 4, ayahNumber: 126, text: 'And to Allah belongs whatever is in the heavens and whatever is on the earth. And ever is Allah, of all things, encompassing.' },
  { surahId: 4, ayahNumber: 127, text: 'And they request from you, [O Muhammad], a [legal] ruling concerning women. Say, "Allah gives you a ruling about them and [about] what has been recited to you in the Book concerning the orphan girls to whom you do not give what is decreed for them - and [yet] you desire to marry them - and concerning the oppressed among children and that you maintain for orphans [their rights] in justice." And whatever you do of good - indeed, Allah is ever Knowing of it.' },
  { surahId: 4, ayahNumber: 128, text: 'And if a woman fears from her husband contempt or evasion, there is no sin upon them if they make terms of settlement between them - and settlement is best. And present in [human] souls is stinginess. But if you do good and fear Allah - then indeed Allah is ever, with what you do, Acquainted.' },
  { surahId: 4, ayahNumber: 129, text: 'And you will never be able to be equal [in feeling] between wives, even if you should strive [to do so]. So do not incline completely [toward one] and leave another hanging. And if you amend [your affairs] and fear Allah - then indeed, Allah is ever Forgiving and Merciful.' },
  { surahId: 4, ayahNumber: 130, text: 'But if they separate [by divorce], Allah will enrich each [of them] from His abundance. And ever is Allah Encompassing and Wise.' },
  { surahId: 4, ayahNumber: 131, text: 'And to Allah belongs whatever is in the heavens and whatever is on the earth. And We have instructed those who were given the Scripture before you and yourselves to fear Allah. But if you disbelieve - then to Allah belongs whatever is in the heavens and whatever is on the earth. And ever is Allah Free of need and Praiseworthy.' },
  { surahId: 4, ayahNumber: 132, text: 'And to Allah belongs whatever is in the heavens and whatever is on the earth. And sufficient is Allah as Disposer of affairs.' },
  { surahId: 4, ayahNumber: 133, text: 'If He wills, He can do away with you, O people, and bring others [in your place]. And ever is Allah competent to do that.' },
  { surahId: 4, ayahNumber: 134, text: 'Whoever desires the reward of this world - then with Allah is the reward of this world and the Hereafter. And ever is Allah Hearing and Seeing.' },
  { surahId: 4, ayahNumber: 135, text: 'O you who have believed, be persistently standing firm in justice, witnesses for Allah, even if it be against yourselves or parents and relatives. Whether one is rich or poor, Allah is more worthy of both. So follow not [personal] inclination, lest you not be just. And if you distort [your testimony] or refuse [to give it], then indeed Allah is ever, with what you do, Acquainted.' },
  { surahId: 4, ayahNumber: 136, text: 'O you who have believed, believe in Allah and His Messenger and the Book that He sent down upon His Messenger and the Scripture which He sent down before. And whoever disbelieves in Allah, His angels, His books, His messengers, and the Last Day has certainly gone far astray.' },
  { surahId: 4, ayahNumber: 137, text: 'Indeed, those who have believed then disbelieved, then believed, then disbelieved, and then increased in disbelief - never will Allah forgive them, nor will He guide them to a way.' },
  { surahId: 4, ayahNumber: 138, text: 'Give tidings to the hypocrites that there is for them a painful punishment -' },
  { surahId: 4, ayahNumber: 139, text: 'Those who take disbelievers as allies instead of the believers. Do they seek with them honor [through power]? But indeed, honor belongs to Allah entirely.' },
  { surahId: 4, ayahNumber: 140, text: 'And it has already come down to you in the Book that when you hear the verses of Allah [recited], they are denied [by them] and ridiculed; so do not sit with them until they enter into another conversation. Indeed, you would then be like them. Indeed Allah will gather the hypocrites and disbelievers in Hell all together -' },
  { surahId: 4, ayahNumber: 141, text: 'Those who wait [and watch] you. Then if you gain a victory from Allah, they say, "Were we not with you?" But if the disbelievers have a success, they say [to them], "Did we not gain the advantage over you, but we protected you from the believers?" Allah will judge between [all of] you on the Day of Resurrection, and never will Allah give the disbelievers over the believers a way [to overcome them].' },
  { surahId: 4, ayahNumber: 142, text: 'Indeed, the hypocrites [think to] deceive Allah, but He is deceiving them. And when they stand for prayer, they stand lazily, showing [themselves to] the people and not remembering Allah except a little,' },
  { surahId: 4, ayahNumber: 143, text: 'Wavering between them, [belonging] neither to the believers nor to the disbelievers. And whoever Allah leaves astray - never will you find for him a way.' },
  { surahId: 4, ayahNumber: 144, text: 'O you who have believed, do not take the disbelievers as allies instead of the believers. Do you wish to give Allah against yourselves a clear case?' },
  { surahId: 4, ayahNumber: 145, text: 'Indeed, the hypocrites will be in the lowest depths of the Fire - and never will you find for them a helper -' },
  { surahId: 4, ayahNumber: 146, text: 'Except for those who repent, correct themselves, hold fast to Allah, and are sincere in their religion for Allah, for those will be with the believers. And Allah is going to give the believers a great reward.' },
  { surahId: 4, ayahNumber: 147, text: 'What would Allah do with your punishment if you are grateful and believe? And ever is Allah Appreciative and Knowing.' },
  { surahId: 4, ayahNumber: 148, text: 'Allah does not like the public mention of evil except by one who has been wronged. And ever is Allah Hearing and Knowing.' },
  { surahId: 4, ayahNumber: 149, text: 'If [instead] you show [some] good or conceal it or pardon an offense - indeed, Allah is ever Pardoning and Competent.' },
  { surahId: 4, ayahNumber: 150, text: 'Indeed, those who disbelieve in Allah and His messengers and wish to discriminate between Allah and His messengers and say, "We believe in some and disbelieve in others," and wish to adopt a way in between -' },
  { surahId: 4, ayahNumber: 151, text: 'Those are the disbelievers, truly. And We have prepared for the disbelievers a humiliating punishment.' },
  { surahId: 4, ayahNumber: 152, text: 'But they who believe in Allah and His messengers and do not discriminate between any of them - to those He is going to give their rewards. And ever is Allah Forgiving and Merciful.' },
  { surahId: 4, ayahNumber: 153, text: 'The People of the Scripture ask you to bring down to them a book from the heaven. But they had asked of Moses [even] greater than that and said, "Show us Allah outright," so the thunderbolt struck them for their wrongdoing. Then they took the calf [for worship] after clear evidences had come to them, and We pardoned that. And We gave Moses a clear authority.' },
  { surahId: 4, ayahNumber: 154, text: 'And We raised over them the mount for [refusal of] their covenant; and We said to them, "Enter the gate bowing humbly", and We said to them, "Do not transgress on the sabbath", and We took from them a solemn covenant.' },
  { surahId: 4, ayahNumber: 155, text: 'And [We cursed them] for their breaking of the covenant and their disbelief in the signs of Allah and their killing of the prophets without right and their saying, "Our hearts are wrapped". Rather, Allah has sealed them because of their disbelief, so they believe not, except for a few.' },
  { surahId: 4, ayahNumber: 156, text: 'And [We cursed them] for their disbelief and their saying against Mary a great slander,' },
  { surahId: 4, ayahNumber: 157, text: 'And [for] their saying, "Indeed, we have killed the Messiah, Jesus, the son of Mary, the messenger of Allah." And they did not kill him, nor did they crucify him; but [another] was made to resemble him to them. And indeed, those who differ over it are in doubt about it. They have no knowledge of it except the following of assumption. And they did not kill him, for certain.' },
  { surahId: 4, ayahNumber: 158, text: 'Rather, Allah raised him to Himself. And ever is Allah Exalted in Might and Wise.' },
  { surahId: 4, ayahNumber: 159, text: 'And there is none from the People of the Scripture but that he will surely believe in Jesus before his death. And on the Day of Resurrection he will be against them a witness.' },
  { surahId: 4, ayahNumber: 160, text: 'For wrongdoing on the part of the Jews, We made unlawful for them [certain] good foods which had been lawful to them, and for their averting from the way of Allah many [people],' },
  { surahId: 4, ayahNumber: 161, text: 'And [for] their taking of usury while they had been forbidden from it, and their consuming of the people\'s wealth unjustly. And we have prepared for the disbelievers among them a painful punishment.' },
  { surahId: 4, ayahNumber: 162, text: 'But those firm in knowledge among them and the believers believe in what has been revealed to you, [O Muhammad], and what was revealed before you. And the establishers of prayer [especially] and the givers of zakah and the believers in Allah and the Last Day - those We will give a great reward.' },
  { surahId: 4, ayahNumber: 163, text: 'Indeed, We have revealed to you, [O Muhammad], as We revealed to Noah and the prophets after him. And we revealed to Abraham, Ishmael, Isaac, Jacob, the Descendants, Jesus, Job, Jonah, Aaron, and Solomon, and to David We gave the book [of Psalms].' },
  { surahId: 4, ayahNumber: 164, text: 'And [We sent] messengers about whom We have related [their stories] to you before and messengers about whom We have not related to you. And Allah spoke to Moses with [direct] speech.' },
  { surahId: 4, ayahNumber: 165, text: '[We sent] messengers as bringers of good tidings and warners so that mankind will have no argument against Allah after the messengers. And ever is Allah Exalted in Might and Wise.' },
  { surahId: 4, ayahNumber: 166, text: 'But Allah bears witness to that which He has revealed to you. He has sent it down with His knowledge, and the angels bear witness [as well]. And sufficient is Allah as Witness.' },
  { surahId: 4, ayahNumber: 167, text: 'Indeed, those who disbelieve and avert [people] from the way of Allah have certainly gone far astray.' },
  { surahId: 4, ayahNumber: 168, text: 'Indeed, those who disbelieve and commit wrong [or injustice] - never will Allah forgive them, nor will He guide them to a path.' },
  { surahId: 4, ayahNumber: 169, text: 'Except the path of Hell; they will abide therein forever. And that, for Allah, is [always] easy.' },
  { surahId: 4, ayahNumber: 170, text: 'O Mankind, the Messenger has come to you with the truth from your Lord, so believe; it is better for you. But if you disbelieve - then indeed, to Allah belongs whatever is in the heavens and earth. And ever is Allah Knowing and Wise.' },
  { surahId: 4, ayahNumber: 171, text: 'O People of the Scripture, do not commit excess in your religion or say about Allah except the truth. The Messiah, Jesus, the son of Mary, was but a messenger of Allah and His word which He directed to Mary and a soul [created at a command] from Him. So believe in Allah and His messengers. And do not say, "Three"; desist - it is better for you. Indeed, Allah is but one God. Exalted is He above having a son. To Him belongs whatever is in the heavens and whatever is on the earth. And sufficient is Allah as Disposer of affairs.' },
  { surahId: 4, ayahNumber: 172, text: 'Never would the Messiah disdain to be a servant of Allah, nor would the angels near [to Him]. And whoever disdains His worship and is arrogant - He will gather them to Himself all together.' },
  { surahId: 4, ayahNumber: 173, text: 'And as for those who believed and did righteous deeds, He will give them in full their rewards and grant them extra from His bounty. But as for those who disdained and were arrogant, He will punish them with a painful punishment, and they will not find for themselves besides Allah any protector or helper.' },
  { surahId: 4, ayahNumber: 174, text: 'O mankind, there has come to you a conclusive proof from your Lord, and We have sent down to you a clear light.' },
  { surahId: 4, ayahNumber: 175, text: 'So those who believe in Allah and hold fast to Him - He will admit them to mercy from Himself and bounty and guide them to Himself on a straight path.' },
  { surahId: 4, ayahNumber: 176, text: 'They request from you a [legal] ruling. Say, "Allah gives you a ruling concerning one having neither descendants nor ascendants [as heirs]." If a man dies, leaving no child but [only] a sister, she will have half of what he left. And he inherits from her if she [dies and] has no child. But if there are two sisters [or more], they will have two-thirds of what he left. If there are both brothers and sisters, the male will have the share of two females. Allah makes clear to you [His law], lest you go astray. And Allah is Knowing of all things.' },
  { surahId: 5, ayahNumber: 1, text: 'O you who have believed, fulfill [all] contracts. Lawful for you are the animals of grazing livestock except for that which is recited to you [in this Qur\'an] - hunting not being permitted while you are in the state of ihram. Indeed, Allah ordains what He intends.' },
  { surahId: 5, ayahNumber: 2, text: 'O you who have believed, do not violate the rites of Allah or [the sanctity of] the sacred month or [neglect the marking of] the sacrificial animals and garlanding [them] or [violate the safety of] those coming to the Sacred House seeking bounty from their Lord and [His] approval. But when you come out of ihram, then [you may] hunt. And do not let the hatred of a people for having obstructed you from al-Masjid al-Haram lead you to transgress. And cooperate in righteousness and piety, but do not cooperate in sin and aggression. And fear Allah; indeed, Allah is severe in penalty.' },
  { surahId: 5, ayahNumber: 3, text: 'Prohibited to you are dead animals, blood, the flesh of swine, and that which has been dedicated to other than Allah, and [those animals] killed by strangling or by a violent blow or by a head-long fall or by the goring of horns, and those from which a wild animal has eaten, except what you [are able to] slaughter [before its death], and those which are sacrificed on stone altars, and [prohibited is] that you seek decision through divining arrows. That is grave disobedience. This day those who disbelieve have despaired of [defeating] your religion; so fear them not, but fear Me. This day I have perfected for you your religion and completed My favor upon you and have approved for you Islam as religion. But whoever is forced by severe hunger with no inclination to sin - then indeed, Allah is Forgiving and Merciful.' },
  { surahId: 5, ayahNumber: 4, text: 'They ask you, [O Muhammad], what has been made lawful for them. Say, "Lawful for you are [all] good foods and [game caught by] what you have trained of hunting animals which you train as Allah has taught you. So eat of what they catch for you, and mention the name of Allah upon it, and fear Allah." Indeed, Allah is swift in account.' },
  { surahId: 5, ayahNumber: 5, text: 'This day [all] good foods have been made lawful, and the food of those who were given the Scripture is lawful for you and your food is lawful for them. And [lawful in marriage are] chaste women from among the believers and chaste women from among those who were given the Scripture before you, when you have given them their due compensation, desiring chastity, not unlawful sexual intercourse or taking [secret] lovers. And whoever denies the faith - his work has become worthless, and he, in the Hereafter, will be among the losers.' },
  { surahId: 5, ayahNumber: 6, text: 'O you who have believed, when you rise to [perform] prayer, wash your faces and your forearms to the elbows and wipe over your heads and wash your feet to the ankles. And if you are in a state of janabah, then purify yourselves. But if you are ill or on a journey or one of you comes from the place of relieving himself or you have contacted women and do not find water, then seek clean earth and wipe over your faces and hands with it. Allah does not intend to make difficulty for you, but He intends to purify you and complete His favor upon you that you may be grateful.' },
  { surahId: 5, ayahNumber: 7, text: 'And remember the favor of Allah upon you and His covenant with which He bound you when you said, "We hear and we obey"; and fear Allah. Indeed, Allah is Knowing of that within the breasts.' },
  { surahId: 5, ayahNumber: 8, text: 'O you who have believed, be persistently standing firm for Allah, witnesses in justice, and do not let the hatred of a people prevent you from being just. Be just; that is nearer to righteousness. And fear Allah; indeed, Allah is Acquainted with what you do.' },
  { surahId: 5, ayahNumber: 9, text: 'Allah has promised those who believe and do righteous deeds [that] for them there is forgiveness and great reward.' },
  { surahId: 5, ayahNumber: 10, text: 'But those who disbelieve and deny Our signs - those are the companions of Hellfire.' },
  { surahId: 5, ayahNumber: 11, text: 'O you who have believed, remember the favor of Allah upon you when a people determined to extend their hands [in aggression] against you, but He withheld their hands from you; and fear Allah. And upon Allah let the believers rely.' },
  { surahId: 5, ayahNumber: 12, text: 'And Allah had already taken a covenant from the Children of Israel, and We delegated from among them twelve leaders. And Allah said, "I am with you. If you establish prayer and give zakah and believe in My messengers and support them and loan Allah a goodly loan, I will surely remove from you your misdeeds and admit you to gardens beneath which rivers flow. But whoever of you disbelieves after that has certainly strayed from the soundness of the way."' },
  { surahId: 5, ayahNumber: 13, text: 'So for their breaking of the covenant We cursed them and made their hearts hard. They distort words from their [proper] usages and have forgotten a portion of that of which they were reminded. And you will still observe deceit among them, except a few of them. But pardon them and overlook [their misdeeds]. Indeed, Allah loves the doers of good.' },
  { surahId: 5, ayahNumber: 14, text: 'And from those who say, "We are Christians" We took their covenant; but they forgot a portion of that of which they were reminded. So We caused among them animosity and hatred until the Day of Resurrection. And Allah is going to inform them about what they used to do.' },
  { surahId: 5, ayahNumber: 15, text: 'O People of the Scripture, there has come to you Our Messenger making clear to you much of what you used to conceal of the Scripture and overlooking much. There has come to you from Allah a light and a clear Book.' },
  { surahId: 5, ayahNumber: 16, text: 'By which Allah guides those who pursue His pleasure to the ways of peace and brings them out from darknesses into the light, by His permission, and guides them to a straight path.' },
  { surahId: 5, ayahNumber: 17, text: 'They have certainly disbelieved who say that Allah is Christ, the son of Mary. Say, "Then who could prevent Allah at all if He had intended to destroy Christ, the son of Mary, or his mother or everyone on the earth?" And to Allah belongs the dominion of the heavens and the earth and whatever is between them. He creates what He wills, and Allah is over all things competent.' },
  { surahId: 5, ayahNumber: 18, text: 'But the Jews and the Christians say, "We are the children of Allah and His beloved." Say, "Then why does He punish you for your sins?" Rather, you are human beings from among those He has created. He forgives whom He wills, and He punishes whom He wills. And to Allah belongs the dominion of the heavens and the earth and whatever is between them, and to Him is the [final] destination.' },
  { surahId: 5, ayahNumber: 19, text: 'O People of the Scripture, there has come to you Our Messenger to make clear to you [the religion] after a period [of suspension] of messengers, lest you say, "There came not to us any bringer of good tidings or a warner." But there has come to you a bringer of good tidings and a warner. And Allah is over all things competent.' },
  { surahId: 5, ayahNumber: 20, text: 'And [mention, O Muhammad], when Moses said to his people, "O my people, remember the favor of Allah upon you when He appointed among you prophets and made you possessors and gave you that which He had not given anyone among the worlds.' },
  { surahId: 5, ayahNumber: 21, text: 'O my people, enter the Holy Land which Allah has assigned to you and do not turn back [from fighting in Allah \'s cause] and [thus] become losers."' },
  { surahId: 5, ayahNumber: 22, text: 'They said, "O Moses, indeed within it is a people of tyrannical strength, and indeed, we will never enter it until they leave it; but if they leave it, then we will enter."' },
  { surahId: 5, ayahNumber: 23, text: 'Said two men from those who feared [to disobey] upon whom Allah had bestowed favor, "Enter upon them through the gate, for when you have entered it, you will be predominant. And upon Allah rely, if you should be believers."' },
  { surahId: 5, ayahNumber: 24, text: 'They said, "O Moses, indeed we will not enter it, ever, as long as they are within it; so go, you and your Lord, and fight. Indeed, we are remaining right here."' },
  { surahId: 5, ayahNumber: 25, text: '[Moses] said, "My Lord, indeed I do not possess except myself and my brother, so part us from the defiantly disobedient people."' },
  { surahId: 5, ayahNumber: 26, text: '[Allah] said, "Then indeed, it is forbidden to them for forty years [in which] they will wander throughout the land. So do not grieve over the defiantly disobedient people."' },
  { surahId: 5, ayahNumber: 27, text: 'And recite to them the story of Adam\'s two sons, in truth, when they both offered a sacrifice [to Allah], and it was accepted from one of them but was not accepted from the other. Said [the latter], "I will surely kill you." Said [the former], "Indeed, Allah only accepts from the righteous [who fear Him].' },
  { surahId: 5, ayahNumber: 28, text: 'If you should raise your hand against me to kill me - I shall not raise my hand against you to kill you. Indeed, I fear Allah, Lord of the worlds.' },
  { surahId: 5, ayahNumber: 29, text: 'Indeed I want you to obtain [thereby] my sin and your sin so you will be among the companions of the Fire. And that is the recompense of wrongdoers."' },
  { surahId: 5, ayahNumber: 30, text: 'And his soul permitted to him the murder of his brother, so he killed him and became among the losers.' },
  { surahId: 5, ayahNumber: 31, text: 'Then Allah sent a crow searching in the ground to show him how to hide the disgrace of his brother. He said, "O woe to me! Have I failed to be like this crow and hide the body of my brother?" And he became of the regretful.' },
  { surahId: 5, ayahNumber: 32, text: 'Because of that, We decreed upon the Children of Israel that whoever kills a soul unless for a soul or for corruption [done] in the land - it is as if he had slain mankind entirely. And whoever saves one - it is as if he had saved mankind entirely. And our messengers had certainly come to them with clear proofs. Then indeed many of them, [even] after that, throughout the land, were transgressors.' },
  { surahId: 5, ayahNumber: 33, text: 'Indeed, the penalty for those who wage war against Allah and His Messenger and strive upon earth [to cause] corruption is none but that they be killed or crucified or that their hands and feet be cut off from opposite sides or that they be exiled from the land. That is for them a disgrace in this world; and for them in the Hereafter is a great punishment,' },
  { surahId: 5, ayahNumber: 34, text: 'Except for those who return [repenting] before you apprehend them. And know that Allah is Forgiving and Merciful.' },
  { surahId: 5, ayahNumber: 35, text: 'O you who have believed, fear Allah and seek the means [of nearness] to Him and strive in His cause that you may succeed.' },
  { surahId: 5, ayahNumber: 36, text: 'Indeed, those who disbelieve - if they should have all that is in the earth and the like of it with it by which to ransom themselves from the punishment of the Day of Resurrection, it will not be accepted from them, and for them is a painful punishment' },
  { surahId: 5, ayahNumber: 37, text: 'They will wish to get out of the Fire, but never are they to emerge therefrom, and for them is an enduring punishment.' },
  { surahId: 5, ayahNumber: 38, text: '[As for] the thief, the male and the female, amputate their hands in recompense for what they committed as a deterrent [punishment] from Allah. And Allah is Exalted in Might and Wise.' },
  { surahId: 5, ayahNumber: 39, text: 'But whoever repents after his wrongdoing and reforms, indeed, Allah will turn to him in forgiveness. Indeed, Allah is Forgiving and Merciful.' },
  { surahId: 5, ayahNumber: 40, text: 'Do you not know that to Allah belongs the dominion of the heavens and the earth? He punishes whom He wills and forgives whom He wills, and Allah is over all things competent.' },
  { surahId: 5, ayahNumber: 41, text: 'O Messenger, let them not grieve you who hasten into disbelief of those who say, "We believe" with their mouths, but their hearts believe not, and from among the Jews. [They are] avid listeners to falsehood, listening to another people who have not come to you. They distort words beyond their [proper] usages, saying "If you are given this, take it; but if you are not given it, then beware." But he for whom Allah intends fitnah - never will you possess [power to do] for him a thing against Allah. Those are the ones for whom Allah does not intend to purify their hearts. For them in this world is disgrace, and for them in the Hereafter is a great punishment.' },
  { surahId: 5, ayahNumber: 42, text: '[They are] avid listeners to falsehood, devourers of [what is] unlawful. So if they come to you, [O Muhammad], judge between them or turn away from them. And if you turn away from them - never will they harm you at all. And if you judge, judge between them with justice. Indeed, Allah loves those who act justly.' },
  { surahId: 5, ayahNumber: 43, text: 'But how is it that they come to you for judgement while they have the Torah, in which is the judgement of Allah? Then they turn away, [even] after that; but those are not [in fact] believers.' },
  { surahId: 5, ayahNumber: 44, text: 'Indeed, We sent down the Torah, in which was guidance and light. The prophets who submitted [to Allah] judged by it for the Jews, as did the rabbis and scholars by that with which they were entrusted of the Scripture of Allah, and they were witnesses thereto. So do not fear the people but fear Me, and do not exchange My verses for a small price. And whoever does not judge by what Allah has revealed - then it is those who are the disbelievers.' },
  { surahId: 5, ayahNumber: 45, text: 'And We ordained for them therein a life for a life, an eye for an eye, a nose for a nose, an ear for an ear, a tooth for a tooth, and for wounds is legal retribution. But whoever gives [up his right as] charity, it is an expiation for him. And whoever does not judge by what Allah has revealed - then it is those who are the wrongdoers.' },
  { surahId: 5, ayahNumber: 46, text: 'And We sent, following in their footsteps, Jesus, the son of Mary, confirming that which came before him in the Torah; and We gave him the Gospel, in which was guidance and light and confirming that which preceded it of the Torah as guidance and instruction for the righteous.' },
  { surahId: 5, ayahNumber: 47, text: 'And let the People of the Gospel judge by what Allah has revealed therein. And whoever does not judge by what Allah has revealed - then it is those who are the defiantly disobedient.' },
  { surahId: 5, ayahNumber: 48, text: 'And We have revealed to you, [O Muhammad], the Book in truth, confirming that which preceded it of the Scripture and as a criterion over it. So judge between them by what Allah has revealed and do not follow their inclinations away from what has come to you of the truth. To each of you We prescribed a law and a method. Had Allah willed, He would have made you one nation [united in religion], but [He intended] to test you in what He has given you; so race to [all that is] good. To Allah is your return all together, and He will [then] inform you concerning that over which you used to differ.' },
  { surahId: 5, ayahNumber: 49, text: 'And judge, [O Muhammad], between them by what Allah has revealed and do not follow their inclinations and beware of them, lest they tempt you away from some of what Allah has revealed to you. And if they turn away - then know that Allah only intends to afflict them with some of their [own] sins. And indeed, many among the people are defiantly disobedient.' },
  { surahId: 5, ayahNumber: 50, text: 'Then is it the judgement of [the time of] ignorance they desire? But who is better than Allah in judgement for a people who are certain [in faith].' },
  { surahId: 5, ayahNumber: 51, text: 'O you who have believed, do not take the Jews and the Christians as allies. They are [in fact] allies of one another. And whoever is an ally to them among you - then indeed, he is [one] of them. Indeed, Allah guides not the wrongdoing people.' },
  { surahId: 5, ayahNumber: 52, text: 'So you see those in whose hearts is disease hastening into [association with] them, saying, "We are afraid a misfortune may strike us." But perhaps Allah will bring conquest or a decision from Him, and they will become, over what they have been concealing within themselves, regretful.' },
  { surahId: 5, ayahNumber: 53, text: 'And those who believe will say, "Are these the ones who swore by Allah their strongest oaths that indeed they were with you?" Their deeds have become worthless, and they have become losers.' },
  { surahId: 5, ayahNumber: 54, text: 'O you who have believed, whoever of you should revert from his religion - Allah will bring forth [in place of them] a people He will love and who will love Him [who are] humble toward the believers, powerful against the disbelievers; they strive in the cause of Allah and do not fear the blame of a critic. That is the favor of Allah; He bestows it upon whom He wills. And Allah is all-Encompassing and Knowing.' },
  { surahId: 5, ayahNumber: 55, text: 'Your ally is none but Allah and [therefore] His Messenger and those who have believed - those who establish prayer and give zakah, and they bow [in worship].' },
  { surahId: 5, ayahNumber: 56, text: 'And whoever is an ally of Allah and His Messenger and those who have believed - indeed, the party of Allah - they will be the predominant.' },
  { surahId: 5, ayahNumber: 57, text: 'O you who have believed, take not those who have taken your religion in ridicule and amusement among the ones who were given the Scripture before you nor the disbelievers as allies. And fear Allah, if you should [truly] be believers.' },
  { surahId: 5, ayahNumber: 58, text: 'And when you call to prayer, they take it in ridicule and amusement. That is because they are a people who do not use reason.' },
  { surahId: 5, ayahNumber: 59, text: 'Say, "O People of the Scripture, do you resent us except [for the fact] that we have believed in Allah and what was revealed to us and what was revealed before and because most of you are defiantly disobedient?"' },
  { surahId: 5, ayahNumber: 60, text: 'Say, "Shall I inform you of [what is] worse than that as penalty from Allah? [It is that of] those whom Allah has cursed and with whom He became angry and made of them apes and pigs and slaves of Taghut. Those are worse in position and further astray from the sound way."' },
  { surahId: 5, ayahNumber: 61, text: 'And when they come to you, they say, "We believe." But they have entered with disbelief [in their hearts], and they have certainly left with it. And Allah is most knowing of what they were concealing.' },
  { surahId: 5, ayahNumber: 62, text: 'And you see many of them hastening into sin and aggression and the devouring of [what is] unlawful. How wretched is what they have been doing.' },
  { surahId: 5, ayahNumber: 63, text: 'Why do the rabbis and religious scholars not forbid them from saying what is sinful and devouring what is unlawful? How wretched is what they have been practicing.' },
  { surahId: 5, ayahNumber: 64, text: 'And the Jews say, "The hand of Allah is chained." Chained are their hands, and cursed are they for what they say. Rather, both His hands are extended; He spends however He wills. And that which has been revealed to you from your Lord will surely increase many of them in transgression and disbelief. And We have cast among them animosity and hatred until the Day of Resurrection. Every time they kindled the fire of war [against you], Allah extinguished it. And they strive throughout the land [causing] corruption, and Allah does not like corrupters.' },
  { surahId: 5, ayahNumber: 65, text: 'And if only the People of the Scripture had believed and feared Allah, We would have removed from them their misdeeds and admitted them to Gardens of Pleasure.' },
  { surahId: 5, ayahNumber: 66, text: 'And if only they upheld [the law of] the Torah, the Gospel, and what has been revealed to them from their Lord, they would have consumed [provision] from above them and from beneath their feet. Among them are a moderate community, but many of them - evil is that which they do.' },
  { surahId: 5, ayahNumber: 67, text: 'O Messenger, announce that which has been revealed to you from your Lord, and if you do not, then you have not conveyed His message. And Allah will protect you from the people. Indeed, Allah does not guide the disbelieving people.' },
  { surahId: 5, ayahNumber: 68, text: 'Say, "O People of the Scripture, you are [standing] on nothing until you uphold [the law of] the Torah, the Gospel, and what has been revealed to you from your Lord." And that which has been revealed to you from your Lord will surely increase many of them in transgression and disbelief. So do not grieve over the disbelieving people.' },
  { surahId: 5, ayahNumber: 69, text: 'Indeed, those who have believed [in Prophet Muhammad] and those [before Him] who were Jews or Sabeans or Christians - those [among them] who believed in Allah and the Last Day and did righteousness - no fear will there be concerning them, nor will they grieve.' },
  { surahId: 5, ayahNumber: 70, text: 'We had already taken the covenant of the Children of Israel and had sent to them messengers. Whenever there came to them a messenger with what their souls did not desire, a party [of messengers] they denied, and another party they killed.' },
  { surahId: 5, ayahNumber: 71, text: 'And they thought there would be no [resulting] punishment, so they became blind and deaf. Then Allah turned to them in forgiveness; then [again] many of them became blind and deaf. And Allah is Seeing of what they do.' },
  { surahId: 5, ayahNumber: 72, text: 'They have certainly disbelieved who say, "Allah is the Messiah, the son of Mary" while the Messiah has said, "O Children of Israel, worship Allah, my Lord and your Lord." Indeed, he who associates others with Allah - Allah has forbidden him Paradise, and his refuge is the Fire. And there are not for the wrongdoers any helpers.' },
  { surahId: 5, ayahNumber: 73, text: 'They have certainly disbelieved who say, "Allah is the third of three." And there is no god except one God. And if they do not desist from what they are saying, there will surely afflict the disbelievers among them a painful punishment.' },
  { surahId: 5, ayahNumber: 74, text: 'So will they not repent to Allah and seek His forgiveness? And Allah is Forgiving and Merciful.' },
  { surahId: 5, ayahNumber: 75, text: 'The Messiah, son of Mary, was not but a messenger; [other] messengers have passed on before him. And his mother was a supporter of truth. They both used to eat food. Look how We make clear to them the signs; then look how they are deluded.' },
  { surahId: 5, ayahNumber: 76, text: 'Say, "Do you worship besides Allah that which holds for you no [power of] harm or benefit while it is Allah who is the Hearing, the Knowing?"' },
  { surahId: 5, ayahNumber: 77, text: 'Say, "O People of the Scripture, do not exceed limits in your religion beyond the truth and do not follow the inclinations of a people who had gone astray before and misled many and have strayed from the soundness of the way."' },
  { surahId: 5, ayahNumber: 78, text: 'Cursed were those who disbelieved among the Children of Israel by the tongue of David and of Jesus, the son of Mary. That was because they disobeyed and [habitually] transgressed.' },
  { surahId: 5, ayahNumber: 79, text: 'They used not to prevent one another from wrongdoing that they did. How wretched was that which they were doing.' },
  { surahId: 5, ayahNumber: 80, text: 'You see many of them becoming allies of those who disbelieved. How wretched is that which they have put forth for themselves in that Allah has become angry with them, and in the punishment they will abide eternally.' },
  { surahId: 5, ayahNumber: 81, text: 'And if they had believed in Allah and the Prophet and in what was revealed to him, they would not have taken them as allies; but many of them are defiantly disobedient.' },
  { surahId: 5, ayahNumber: 82, text: 'You will surely find the most intense of the people in animosity toward the believers [to be] the Jews and those who associate others with Allah; and you will find the nearest of them in affection to the believers those who say, "We are Christians." That is because among them are priests and monks and because they are not arrogant.' },
  { surahId: 5, ayahNumber: 83, text: 'And when they hear what has been revealed to the Messenger, you see their eyes overflowing with tears because of what they have recognized of the truth. They say, "Our Lord, we have believed, so register us among the witnesses.' },
  { surahId: 5, ayahNumber: 84, text: 'And why should we not believe in Allah and what has come to us of the truth? And we aspire that our Lord will admit us [to Paradise] with the righteous people."' },
  { surahId: 5, ayahNumber: 85, text: 'So Allah rewarded them for what they said with gardens [in Paradise] beneath which rivers flow, wherein they abide eternally. And that is the reward of doers of good.' },
  { surahId: 5, ayahNumber: 86, text: 'But those who disbelieved and denied Our signs - they are the companions of Hellfire.' },
  { surahId: 5, ayahNumber: 87, text: 'O you who have believed, do not prohibit the good things which Allah has made lawful to you and do not transgress. Indeed, Allah does not like transgressors.' },
  { surahId: 5, ayahNumber: 88, text: 'And eat of what Allah has provided for you [which is] lawful and good. And fear Allah, in whom you are believers.' },
  { surahId: 5, ayahNumber: 89, text: 'Allah will not impose blame upon you for what is meaningless in your oaths, but He will impose blame upon you for [breaking] what you intended of oaths. So its expiation is the feeding of ten needy people from the average of that which you feed your [own] families or clothing them or the freeing of a slave. But whoever cannot find [or afford it] - then a fast of three days [is required]. That is the expiation for oaths when you have sworn. But guard your oaths. Thus does Allah make clear to you His verses that you may be grateful.' },
  { surahId: 5, ayahNumber: 90, text: 'O you who have believed, indeed, intoxicants, gambling, [sacrificing on] stone alters [to other than Allah], and divining arrows are but defilement from the work of Satan, so avoid it that you may be successful.' },
  { surahId: 5, ayahNumber: 91, text: 'Satan only wants to cause between you animosity and hatred through intoxicants and gambling and to avert you from the remembrance of Allah and from prayer. So will you not desist?' },
  { surahId: 5, ayahNumber: 92, text: 'And obey Allah and obey the Messenger and beware. And if you turn away - then know that upon Our Messenger is only [the responsibility for] clear notification.' },
  { surahId: 5, ayahNumber: 93, text: 'There is not upon those who believe and do righteousness [any] blame concerning what they have eaten [in the past] if they [now] fear Allah and believe and do righteous deeds, and then fear Allah and believe, and then fear Allah and do good; and Allah loves the doers of good.' },
  { surahId: 5, ayahNumber: 94, text: 'O you who have believed, Allah will surely test you through something of the game that your hands and spears [can] reach, that Allah may make evident those who fear Him unseen. And whoever transgresses after that - for him is a painful punishment.' },
  { surahId: 5, ayahNumber: 95, text: 'O you who have believed, do not kill game while you are in the state of ihram. And whoever of you kills it intentionally - the penalty is an equivalent from sacrificial animals to what he killed, as judged by two just men among you as an offering [to Allah] delivered to the Ka\'bah, or an expiation: the feeding of needy people or the equivalent of that in fasting, that he may taste the consequence of his deed. Allah has pardoned what is past; but whoever returns [to violation], then Allah will take retribution from him. And Allah is Exalted in Might and Owner of Retribution.' },
  { surahId: 5, ayahNumber: 96, text: 'Lawful to you is game from the sea and its food as provision for you and the travelers, but forbidden to you is game from the land as long as you are in the state of ihram. And fear Allah to whom you will be gathered.' },
  { surahId: 5, ayahNumber: 97, text: 'Allah has made the Ka\'bah, the Sacred House, standing for the people and [has sanctified] the sacred months and the sacrificial animals and the garlands [by which they are identified]. That is so you may know that Allah knows what is in the heavens and what is in the earth and that Allah is Knowing of all things.' },
  { surahId: 5, ayahNumber: 98, text: 'Know that Allah is severe in penalty and that Allah is Forgiving and Merciful.' },
  { surahId: 5, ayahNumber: 99, text: 'Not upon the Messenger is [responsibility] except [for] notification. And Allah knows whatever you reveal and whatever you conceal.' },
  { surahId: 5, ayahNumber: 100, text: 'Say, "Not equal are the evil and the good, although the abundance of evil might impress you." So fear Allah, O you of understanding, that you may be successful.' },
  { surahId: 5, ayahNumber: 101, text: 'O you who have believed, do not ask about things which, if they are shown to you, will distress you. But if you ask about them while the Qur\'an is being revealed, they will be shown to you. Allah has pardoned that which is past; and Allah is Forgiving and Forbearing.' },
  { surahId: 5, ayahNumber: 102, text: 'A people asked such [questions] before you; then they became thereby disbelievers.' },
  { surahId: 5, ayahNumber: 103, text: 'Allah has not appointed [such innovations as] bahirah or sa\'ibah or wasilah or ham. But those who disbelieve invent falsehood about Allah, and most of them do not reason.' },
  { surahId: 5, ayahNumber: 104, text: 'And when it is said to them, "Come to what Allah has revealed and to the Messenger," they say, "Sufficient for us is that upon which we found our fathers." Even though their fathers knew nothing, nor were they guided?' },
  { surahId: 5, ayahNumber: 105, text: 'O you who have believed, upon you is [responsibility for] yourselves. Those who have gone astray will not harm you when you have been guided. To Allah is you return all together; then He will inform you of what you used to do.' },
  { surahId: 5, ayahNumber: 106, text: 'O you who have believed, testimony [should be taken] among you when death approaches one of you at the time of bequest - [that of] two just men from among you or two others from outside if you are traveling through the land and the disaster of death should strike you. Detain them after the prayer and let them both swear by Allah if you doubt [their testimony, saying], "We will not exchange our oath for a price, even if he should be a near relative, and we will not withhold the testimony of Allah. Indeed, we would then be of the sinful."' },
  { surahId: 5, ayahNumber: 107, text: 'But if it is found that those two were guilty of perjury, let two others stand in their place [who are] foremost [in claim] from those who have a lawful right. And let them swear by Allah, "Our testimony is truer than their testimony, and we have not transgressed. Indeed, we would then be of the wrongdoers."' },
  { surahId: 5, ayahNumber: 108, text: 'That is more likely that they will give testimony according to its [true] objective, or [at least] they would fear that [other] oaths might be taken after their oaths. And fear Allah and listen; and Allah does not guide the defiantly disobedient people.' },
  { surahId: 5, ayahNumber: 109, text: '[Be warned of] the Day when Allah will assemble the messengers and say, "What was the response you received?" They will say, "We have no knowledge. Indeed, it is You who is Knower of the unseen"' },
  { surahId: 5, ayahNumber: 110, text: '[The Day] when Allah will say, "O Jesus, Son of Mary, remember My favor upon you and upon your mother when I supported you with the Pure Spirit and you spoke to the people in the cradle and in maturity; and [remember] when I taught you writing and wisdom and the Torah and the Gospel; and when you designed from clay [what was] like the form of a bird with My permission, then you breathed into it, and it became a bird with My permission; and you healed the blind and the leper with My permission; and when you brought forth the dead with My permission; and when I restrained the Children of Israel from [killing] you when you came to them with clear proofs and those who disbelieved among them said, "This is not but obvious magic."' },
  { surahId: 5, ayahNumber: 111, text: 'And [remember] when I inspired to the disciples, "Believe in Me and in My messenger Jesus." They said, "We have believed, so bear witness that indeed we are Muslims [in submission to Allah]."' },
  { surahId: 5, ayahNumber: 112, text: '[And remember] when the disciples said, "O Jesus, Son of Mary, can your Lord send down to us a table [spread with food] from the heaven? [Jesus] said," Fear Allah, if you should be believers."' },
  { surahId: 5, ayahNumber: 113, text: 'They said, "We wish to eat from it and let our hearts be reassured and know that you have been truthful to us and be among its witnesses."' },
  { surahId: 5, ayahNumber: 114, text: 'Said Jesus, the son of Mary, "O Allah, our Lord, send down to us a table [spread with food] from the heaven to be for us a festival for the first of us and the last of us and a sign from You. And provide for us, and You are the best of providers."' },
  { surahId: 5, ayahNumber: 115, text: 'Allah said, "Indeed, I will sent it down to you, but whoever disbelieves afterwards from among you - then indeed will I punish him with a punishment by which I have not punished anyone among the worlds."' },
  { surahId: 5, ayahNumber: 116, text: 'And [beware the Day] when Allah will say, "O Jesus, Son of Mary, did you say to the people, \'Take me and my mother as deities besides Allah?\'" He will say, "Exalted are You! It was not for me to say that to which I have no right. If I had said it, You would have known it. You know what is within myself, and I do not know what is within Yourself. Indeed, it is You who is Knower of the unseen.' },
  { surahId: 5, ayahNumber: 117, text: 'I said not to them except what You commanded me - to worship Allah, my Lord and your Lord. And I was a witness over them as long as I was among them; but when You took me up, You were the Observer over them, and You are, over all things, Witness.' },
  { surahId: 5, ayahNumber: 118, text: 'If You should punish them - indeed they are Your servants; but if You forgive them - indeed it is You who is the Exalted in Might, the Wise.' },
  { surahId: 5, ayahNumber: 119, text: 'Allah will say, "This is the Day when the truthful will benefit from their truthfulness." For them are gardens [in Paradise] beneath which rivers flow, wherein they will abide forever, Allah being pleased with them, and they with Him. That is the great attainment.' },
  { surahId: 5, ayahNumber: 120, text: 'To Allah belongs the dominion of the heavens and the earth and whatever is within them. And He is over all things competent.' },
];
